INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Compare single, double and closed circulatory systems.', 'Single (e.g. fish): blood passes through the heart once per circuit; gill -> body. Double (mammals): twice per circuit (pulmonary + systemic), maintaining higher pressures. Closed: blood remains within vessels (mammals); open (insects): haemolymph bathes tissues.', 1, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Describe a single cardiac cycle.', 'Atrial systole: atria contract, AV valves open, ventricles fill. Ventricular systole: AV valves close (lub), ventricles contract, SL valves open, blood ejected. Diastole: SL valves close (dub), all chambers relax, atria refill. Cycle ~0.8 s at 75 bpm.', 2, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Compare arteries, veins and capillaries.', 'Arteries: thick muscular wall, narrow lumen, elastic, carry oxygenated blood (except pulmonary) at high pressure. Veins: thin wall, wide lumen, valves prevent backflow at low pressure. Capillaries: one cell thick endothelium, narrow, large total SA -> exchange.', 3, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Why is water described as a polar molecule?', 'O is more electronegative than H, creating a partial negative charge on O and partial positives on H. Water molecules form hydrogen bonds, giving high specific heat capacity, latent heat of vaporisation, cohesion, and excellent solvent properties.', 4, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Distinguish saturated, monounsaturated and polyunsaturated fatty acids.', 'Saturated: no C=C, straight chain, solid (animal fats). Monounsaturated: one C=C; polyunsaturated: 2+ C=C, kinked chains -> oils, liquid. cis/trans isomerism affects health: trans fats raise LDL.', 5, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Compare HDL and LDL.', 'LDL (low-density): transports cholesterol from liver to tissues; high LDL contributes to atheromas. HDL (high-density): returns cholesterol from tissues to liver. A high HDL : LDL ratio is associated with reduced cardiovascular disease risk.', 6, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Describe the formation of an atheroma and its consequences.', 'Damage to endothelium -> inflammation; LDL and white blood cells accumulate in the artery wall, forming a fibrous plaque (atheroma). Lumen narrows; elasticity falls; BP rises; plaque rupture -> thrombosis -> heart attack or stroke.', 7, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'List CVD risk factors and how each contributes.', 'Genetics, age, gender. Modifiable: high BP, high LDL, smoking (CO reduces O2 capacity, nicotine raises BP), diet (saturated/trans fats, salt), inactivity, obesity, diabetes. Each damages endothelium or alters blood lipids.', 8, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Define correlation vs causation, and identify confounding variables.', 'Correlation: two variables vary together. Causation: one variable directly produces the change in the other. Confounding variables: a third factor that affects both (e.g. age, smoking). Studies must control these to identify true causation.', 9, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Compare cohort and case-control studies.', 'Cohort: a group is followed forward in time, recording outcomes (lung cancer in smokers vs non-smokers). Case-control: starts with cases (lung cancer patients) and controls, looks back at exposures (smoking). Cohort is stronger evidence but slower.', 10, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Describe how cholesterol-lowering treatments work.', 'Statins inhibit HMG-CoA reductase, the liver enzyme that makes cholesterol. Liver cells then take up more LDL from the blood, lowering blood LDL and total cholesterol. Benefit: reduced CVD risk. Risks: side effects such as muscle pain and liver damage, and the need to take them long-term. Plant stanols/sterols reduce absorption of cholesterol from the gut. (The other 9BN0 CVD treatments act differently: antihypertensives lower blood pressure; anticoagulants such as warfarin and platelet inhibitors such as aspirin reduce clotting.)', 11, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Define risk and probability and calculate from data.', 'Risk = probability of an event = number of events / total. Relative risk = exposure group risk / unexposed risk. e.g. if smokers'' risk = 0.2, non-smokers'' = 0.05, RR = 4 -> 4-fold higher risk.', 12, 'alevel'),
  ('Biology', 'Edexcel A', 'S1', 'Lifestyle, Health and Risk', 'Outline how lifestyle interventions reduce CVD risk.', 'Stop smoking, reduce saturated/trans fats and salt, increase fruit/veg/fibre, exercise regularly, maintain healthy BMI, moderate alcohol. These lower BP and LDL, improve insulin sensitivity, and reduce inflammation.', 13, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe the structure of haemoglobin and oxygen binding.', 'Haemoglobin is a globular protein with quaternary structure: four polypeptide chains (2 alpha, 2 beta), each folded around a haem group containing Fe2+ that binds one O2, so each molecule carries up to 4 O2. The chains fold with hydrophilic R groups on the outside, making it soluble in plasma. Compare collagen, a fibrous protein: three insoluble chains wound into a rope-like triple helix, giving tensile strength.', 1, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe the structure of DNA.', 'A nucleotide = phosphate + deoxyribose + base (A, T, C or G). Polynucleotide strands joined by phosphodiester bonds. Two antiparallel strands held by H-bonds: A=T (2), G≡C (3). Twisted into a right-handed double helix.', 2, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Outline the genetic code.', 'Triplet, non-overlapping, degenerate, (almost) universal. Start codon AUG; three stop codons (UAA, UAG, UGA). With 4 possible bases at each of 3 positions there are 4^3 = 64 codons for 20 amino acids. Because of this redundancy (degeneracy), some base substitutions are silent.', 3, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe transcription and post-transcriptional modification.', 'RNA polymerase joins free RNA nucleotides to a template strand (U replaces T) -> pre-mRNA. Splicing removes introns; exons rejoin. 5'' cap and poly-A tail added. Mature mRNA exits via nuclear pore.', 4, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe translation in detail.', 'Small ribosomal subunit binds mRNA; tRNA carrying methionine binds AUG; large subunit completes ribosome. Next tRNA binds complementary codon; peptide bond forms. Ribosome translocates one codon. Continues until a stop codon -> polypeptide released.', 5, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe types of gene mutations and outcomes.', 'Substitution: silent (same amino acid), missense (different amino acid) or nonsense (stop codon -> truncated protein). Insertion or deletion of bases not in a multiple of 3: frameshift -> every downstream codon changed, usually a non-functional protein. The effect depends on how the change alters the protein''s structure and function. Examples: sickle-cell anaemia (substitution, Glu -> Val in beta-globin); CF delta F508 (deletion of 3 nucleotides removing one amino acid, phenylalanine 508, with no frameshift, so CFTR misfolds and is degraded).', 6, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Outline cystic fibrosis at the molecular level.', 'Mutation in the CFTR gene (chr 7) — most commonly delta F508. CFTR is a chloride channel. Faulty channel -> thick mucus in airways, gut, reproductive system. Treatments target symptoms (physiotherapy, mucolytics) and the cause (CFTR modulators, gene therapy).', 7, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe how cystic fibrosis is inherited.', 'Autosomal recessive: two cf alleles needed (one from each parent). Carriers (Cc) show no symptoms. Two carriers x: 1/4 affected, 1/2 carriers, 1/4 unaffected. Genetic counselling and prenatal testing available.', 8, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe phospholipid bilayer structure.', 'Two layers of phospholipids: hydrophilic phosphate heads point outward (towards aqueous); hydrophobic fatty acid tails point inward. The membrane is fluid; cholesterol regulates fluidity; proteins are embedded as channels, carriers and receptors.', 9, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Compare diffusion, facilitated diffusion, osmosis and active transport.', 'Diffusion: passive, lipid-soluble or gases, no protein. Facilitated diffusion: passive via channel/carrier proteins. Osmosis: passive water movement down water-potential gradient. Active transport: against gradient, ATP-driven by carrier proteins.', 10, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe how Na+ and Cl- normally cross airway epithelium and how CF disrupts this.', 'Normal: Cl- ions move out through CFTR channels into mucus; Na+ follows; water follows osmotically -> thin watery mucus. CF: faulty CFTR -> Cl- cannot leave; Na+ moves into cell instead; water leaves mucus -> thick sticky mucus.', 11, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe the structure of the lungs and gas exchange.', 'Trachea -> bronchi -> bronchioles -> alveoli (~300 million; ~70 m^2). Alveoli: thin squamous epithelium, surrounded by capillaries (also one cell thick), surfactant lining, ventilated by breathing -> O2 diffuses to blood, CO2 diffuses out.', 12, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Outline the role of cilia and goblet cells.', 'Goblet cells secrete mucus that traps pathogens and dust. Ciliated epithelial cells beat to move mucus up to the throat where it is swallowed (mucociliary escalator). Smoking paralyses cilia -> chronic cough.', 13, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Describe pre-natal genetic testing for CF (CVS and amniocentesis).', 'CVS (10-13 weeks): biopsy of chorionic villi, faster, slightly higher miscarriage risk (~1%). Amniocentesis (15-20 weeks): sample of amniotic fluid containing fetal cells; lower miscarriage risk (~0.5%) but later. PCR / genetic analysis of CFTR gene.', 14, 'alevel'),
  ('Biology', 'Edexcel A', 'S2', 'Genes and Health', 'Outline ethical considerations of genetic testing.', 'Benefits: informed reproductive choices, treatment planning. Issues: psychological impact, insurance discrimination, privacy, potential for selective termination, parental disagreements, mis-diagnosis. Pre-test counselling is essential.', 15, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Compare DNA in eukaryotes vs prokaryotes.', 'Eukaryotic DNA: linear, in nucleus, wound around histones, has introns and exons. Prokaryotic DNA: circular, in cytoplasm (nucleoid), no histones, no introns. Plasmids may also be present.', 1, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Describe the eukaryotic cell cycle.', 'G1: cell growth, organelle replication. S: DNA replication. G2: further growth, error check. M: mitosis (PMAT). Cytokinesis. Checkpoints (G1/S, G2/M, spindle) prevent damaged cells progressing.', 2, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Outline the four stages of mitosis.', 'Prophase: chromosomes condense (sister chromatids visible), nuclear envelope breaks down, centrosomes move to poles. Metaphase: chromosomes line up on equator. Anaphase: spindle pulls sister chromatids to poles. Telophase: nuclear envelopes reform.', 3, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Compare mitosis and meiosis.', 'Mitosis: 1 division, 2 diploid identical daughter cells, growth/repair. Meiosis: 2 divisions, 4 haploid genetically distinct gametes, with independent assortment and crossing over. Source of variation -> evolution.', 4, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Describe two sources of genetic variation in meiosis.', 'Independent assortment: homologous chromosomes line up randomly in metaphase I (and sister chromatids in metaphase II). Crossing over: in prophase I, non-sister chromatids exchange DNA at chiasmata, forming new allele combinations.', 5, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Define totipotent, pluripotent, multipotent and unipotent.', 'Totipotent: any cell type incl. extra-embryonic (e.g. zygote). Pluripotent: any embryonic cell type (e.g. embryonic stem cells). Multipotent: limited types (e.g. haematopoietic stem cells). Unipotent: one type (e.g. cardiac muscle progenitor).', 6, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Outline how stem cells differentiate.', 'Differentiation results from selective gene expression. Specific TFs activate cell-type-specific genes; epigenetic changes (DNA methylation, histone modification) silence others. Position-dependent signals (morphogens) and the cells'' microenvironment guide specialisation.', 7, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Outline benefits and ethical issues of using human embryonic stem cells.', 'Benefits: pluripotent -> potential regenerative therapies (Parkinson''s, spinal injury). Ethics: destruction of embryos; iPS cells offer an alternative with fewer concerns. Strict regulation (HFEA in the UK).', 8, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Describe how genes and environment interact.', 'Genotype sets potential; phenotype is the result of gene expression + environment. e.g. height (genetic potential limited by nutrition); MZ twins'' methylomes drift over time; many traits are polygenic and multifactorial.', 9, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Compare continuous and discontinuous variation.', 'Continuous: range of values (height, mass), polygenic and influenced by environment, normal distribution. Discontinuous: distinct categories (blood group), usually one or few genes, environment little effect; bar chart distribution.', 10, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Describe cell signalling and gene expression.', 'Signal molecule (e.g. hormone) binds a receptor -> transduction (often a phosphorylation cascade) -> activates TFs that bind DNA, switching specific genes on/off. Allows tissue-specific responses.', 11, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'Outline mammalian fertilisation.', 'Sperm acrosome reaction: enzymes digest zona pellucida. Sperm membrane fuses with oocyte. Cortical reaction prevents polyspermy. Sperm nucleus enters; meiosis II completes; haploid pronuclei fuse -> diploid zygote. Cleavage starts.', 12, 'alevel'),
  ('Biology', 'Edexcel A', 'S3', 'Voice of the Genome', 'How are chromosomes packaged in the nucleus?', 'DNA wraps around 8 histone proteins to form a nucleosome (~146 bp). Nucleosomes coil into a 30 nm fibre and fold into chromatin. Heterochromatin (densely packed) silences genes; euchromatin (open) is transcribed.', 13, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Outline the eight taxonomic ranks and three domains.', 'Domain, Kingdom, Phylum, Class, Order, Family, Genus, Species. Three domains (Woese): Bacteria, Archaea, Eukarya — based on rRNA sequences, membrane lipids, and genome organisation.', 1, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Define a species and describe two ways to define it.', 'Phylogenetic: shared evolutionary lineage on a tree of life. Biological: members can interbreed to produce fertile offspring. Issues: hybrid sterility (mules), asexual species, ring species. Modern molecular comparisons supplement morphology.', 2, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'How are molecular methods used to classify organisms?', 'Direct DNA / amino acid sequence comparison gives quantitative similarity. Closer relatives share more conserved sequences. Confirms or revises classifications based on morphology and reveals evolutionary relationships hidden by convergent evolution.', 3, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Define biodiversity at three levels.', 'Habitat: number of habitats in an area. Species: richness (count) and evenness (relative abundance). Genetic: variety of alleles within a population. All three vary independently and matter for ecosystem stability.', 4, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Calculate the index of diversity (9BN0).', '9BN0 index of diversity: D = N(N - 1) / sum of n(n - 1), where N = total number of organisms of all species and n = number of individuals of each species. D = 1 if only one species is present; the higher the value, the more diverse the habitat. It takes into account both species richness and the evenness of abundance, so habitats can be compared.', 5, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Define endemism and give an example.', 'A species found only in a single restricted area. e.g. lemurs (Madagascar), Galapagos finches. Endemic species are vulnerable to extinction because their entire range can be affected by a single disturbance.', 6, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Describe the structure of plant cell walls.', 'Cellulose microfibrils (beta-1,4 glucose) crosslinked by hemicellulose and embedded in pectin. Lignin adds strength to xylem and sclerenchyma. Plasmodesmata link cells. The wall provides support, shape and tensile strength against turgor pressure.', 7, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Compare xylem and phloem.', 'Xylem: dead, lignified tubes carrying water/minerals from root to leaves; mass flow driven by transpiration tension. Phloem: living sieve tubes with companion cells, transports assimilates (sucrose) from sources to sinks by mass flow.', 8, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'How are plants used in medicine? (Drug discovery)', 'Examples: aspirin from willow bark salicylates, taxol from yew (cancer), digitalis from foxglove (heart). Bioprospecting screens biodiverse regions; loss of biodiversity means losing potential drugs.', 9, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Describe testing of new drugs (William Withering / clinical trials).', 'Withering used systematic patient observation to determine the correct dose of digitalis. Modern trials: pre-clinical (cells, animals), Phase I (safety in healthy volunteers), II (efficacy), III (large randomised trial vs placebo or current treatment), IV (post-market surveillance).', 10, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Compare in situ and ex situ conservation.', 'In situ: protect species in natural habitat (national parks, reserves) — preserves ecological interactions but vulnerable to disasters. Ex situ: zoos, seed banks, botanical gardens — controlled but smaller gene pool, risk of inbreeding.', 11, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Describe a seed bank.', 'Stores dried, low-T seeds (e.g. Millennium Seed Bank, Kew) ex situ. Long-term storage preserves genetic diversity, crop wild relatives, and species at risk of extinction. Limitations: only seed-bearing plants, viability declines, periodic germination tests required.', 12, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'Outline how zoos contribute to species conservation.', 'Captive breeding programmes (e.g. Arabian oryx, giant panda); coordinated international stud books prevent inbreeding; reintroduction projects; education and research. Critics raise concerns about welfare and habitat loss being the root problem.', 13, 'alevel'),
  ('Biology', 'Edexcel A', 'S4', 'Biodiversity and Natural Resources', 'State Hardy-Weinberg principle and equations.', 'Allele frequencies stay constant across generations if: large population, no migration, no mutation, no selection, random mating. p + q = 1; p^2 + 2pq + q^2 = 1.', 14, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Write the photosynthesis equation and identify oxidation/reduction.', '6CO2 + 6H2O -> C6H12O6 + 6O2 (sunlight). CO2 is reduced (gains H/electrons) to glucose. H2O is oxidised to O2 in photolysis at PSII.', 1, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Outline the light-dependent reactions.', 'Photolysis at PSII: 2H2O -> 4H+ + 4e- + O2. Excited e- pass down ETC, pumping H+ into thylakoid lumen -> ATP via chemiosmosis. NADP+ + H+ + 2e- -> NADPH. Cyclic photophosphorylation produces only ATP.', 2, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Describe the Calvin cycle.', 'CO2 + RuBP -> 2 GP (catalysed by RuBisCO). GP reduced to TP using ATP and NADPH. Some TP forms hexose; most regenerates RuBP using ATP. Six turns yield one glucose.', 3, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Describe how light, CO2 and temperature affect photosynthesis.', 'Each can be the limiting factor when it is in shortest supply. Low light: the light-dependent reactions are limited, so little ATP and reduced NADP is supplied to the Calvin cycle. Low CO2: carbon fixation by RuBisCO in the Calvin cycle is limited. Temperature: below the optimum, enzyme-controlled reactions (e.g. RuBisCO) slow. Above the optimum, the rate falls as stomata close to reduce water loss (less CO2 uptake) and enzymes lose activity, denaturing at high temperatures (around 40 degrees C and above).', 4, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Define an ecosystem and give an example food chain.', 'Ecosystem = a community of organisms interacting with each other and with their abiotic environment. Example food chain: grass -> rabbit -> fox (producer -> primary consumer -> secondary consumer). Energy enters when producers fix light energy by photosynthesis (GPP); the energy remaining after plant respiration (NPP = GPP - R) is available to primary consumers. Typically only about 10% of energy passes from one trophic level to the next.', 5, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Define and calculate net primary productivity (NPP).', 'GPP = total chemical energy fixed by producers per area per time. NPP = GPP - R (respiration). Units: kJ m^-2 yr^-1. NPP is energy available to next trophic level.', 6, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Describe the carbon cycle.', 'Photosynthesis fixes CO2 into organic compounds; respiration, combustion and decomposition return CO2. Carbon stored in biomass, soil, oceans (HCO3-), fossil fuels. Anthropogenic CO2 (fossil fuel burning, deforestation) increases atmospheric levels.', 7, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'List evidence for climate change.', 'Direct: ice core CO2 / temperature records, atmospheric CO2 measurements (Mauna Loa), satellite data, sea-level rise, glacier retreat. Indirect: dendrochronology, pollen analysis, isotope ratios in foraminifera. Multiple independent lines converge on warming.', 8, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Explain how rising temperatures affect species distribution.', 'Species shift poleward and upward in altitude as temperatures rise; phenological mismatches (flowering vs pollinators) occur; range contractions if no migration possible (e.g. mountain-top species). Loss of habitat and mismatched timing reduce reproductive success.', 9, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Describe primary succession from bare rock.', 'Pioneer species (e.g. lichens) colonise bare rock, weather it and add organic matter. Mosses follow, then small plants, grasses, shrubs and finally woodland (climax). Each stage modifies the abiotic conditions for the next.', 10, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Compare deflected and secondary succession.', 'Secondary: starts on existing soil after disturbance (e.g. fire); succession proceeds as for primary but faster. Deflected: human activity (mowing, grazing) holds the community at an earlier seral stage (heathland, chalk grassland) — often biodiverse.', 11, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Describe natural selection in peppered moths and antibiotic resistance.', 'Peppered moth: dark form favoured during industrial pollution (camouflage on sooty trees); light form returns after Clean Air Act. Antibiotic resistance: random mutations in bacteria; resistant variants survive antibiotic treatment and reproduce.', 12, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'Compare allopatric and sympatric speciation.', 'Allopatric: geographical isolation -> divergent selection / drift -> reproductive isolation. Sympatric: arises within a population without a physical barrier (polyploidy in plants, behavioural / temporal isolation).', 13, 'alevel'),
  ('Biology', 'Edexcel A', 'S5', 'On the Wild Side', 'How can we mitigate climate change biologically?', 'Reduce CO2 emissions (fossil fuel substitution, energy efficiency); reforestation and afforestation; rewetting peatlands; protect oceans (blue carbon); reduce deforestation; carbon capture and storage; soil management. Both supply-side and demand-side action needed.', 14, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Compare types of pathogens and give one example each.', 'Bacteria: prokaryote, peptidoglycan wall (e.g. TB Mycobacterium tuberculosis). Virus: nucleic acid + capsid, hijacks host (HIV). Fungi: eukaryote, hyphae (athlete''s foot Trichophyton). Protoctist: eukaryote (Plasmodium - malaria).', 1, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Describe non-specific (innate) defences.', 'Skin barrier; mucous membranes; lysozyme in tears/saliva; gastric acid; ciliated epithelia; phagocytosis (neutrophils, macrophages); inflammation (histamine, vasodilation); fever (raised T inhibits pathogens). Fast but non-specific.', 2, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Describe phagocytosis step-by-step.', 'Phagocyte chemotaxes towards pathogen, recognises by surface receptors, engulfs by endocytosis -> phagosome. Lysosomes fuse with phagosome -> phagolysosome; lysozyme digests pathogen. Antigens displayed on MHC for T-cell activation.', 3, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Compare T helper, T killer and B cells.', 'T helper: bind APCs, release cytokines that activate other cells. T killer: directly kill infected/cancer cells (perforin, granzymes). B cells: differentiate into plasma cells (antibodies) or memory cells once selected by their specific antigen.', 4, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Describe antibody structure and four functions.', 'Y-shape, two heavy + two light chains, constant + variable regions, two antigen-binding sites. Functions: agglutination, opsonisation (mark for phagocytosis), neutralisation of toxins, activation of complement.', 5, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Compare primary and secondary immune responses.', 'Primary: long lag (about 1-2 weeks to peak) while the few B and T cells specific to the antigen are selected and cloned; low antibody peak; symptoms often develop. Memory B and T cells form. Secondary: memory cells respond quickly, so antibody levels rise within a few days and reach a much higher, longer-lasting peak; the pathogen is usually destroyed before symptoms appear. Forms the basis of long-term immunity.', 6, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Describe vaccination and herd immunity.', 'Vaccines contain weakened/inactivated pathogens or antigens, triggering primary response and memory cells without disease. If many in a population are immune, the pathogen cannot spread (herd immunity), protecting unvaccinated individuals.', 7, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Distinguish active, passive, natural and artificial immunity.', 'Active: own antibodies / memory (long-term). Passive: received antibodies (short-term). Natural: through life (infection / breast milk). Artificial: vaccines (active) or antibody injection (passive, e.g. anti-tetanus).', 8, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'How do antibiotics work?', 'Bactericidal: kill bacteria (penicillin disrupts peptidoglycan synthesis -> weak walls -> lysis). Bacteriostatic: prevent growth (tetracyclines block 70S ribosomes -> halt protein synthesis). Selective toxicity: target features absent in human cells.', 9, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'How does antibiotic resistance evolve?', 'Random mutation gives resistance (e.g. beta-lactamase, modified penicillin-binding proteins). Antibiotics select for resistant strains; resistance genes spread via plasmid conjugation (horizontal transfer). Misuse and incomplete courses accelerate this.', 10, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Describe how time of death is estimated.', 'Algor mortis: ~1.5 °C drop per hour (first 12 h). Rigor mortis: stiffness from ~2 h, peak at 12 h, fades by 36 h. Hypostasis (livor): blood pooling, fixed by ~12 h. Insect succession (entomology). Stomach contents.', 11, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Outline DNA profiling using STRs.', 'Extract DNA, amplify short tandem repeat (STR) regions by PCR, separate fragments by gel/capillary electrophoresis. Each individual has a near-unique STR profile -> banding pattern. Used in identification, paternity, forensics.', 12, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Outline polymerase chain reaction (PCR).', 'Cycles: 95 °C denature -> ~55 °C anneal primers -> 72 °C extend with Taq polymerase. Each cycle doubles DNA -> 2^n copies after n cycles. Used in cloning, sequencing and DNA profiling.', 13, 'alevel'),
  ('Biology', 'Edexcel A', 'S6', 'Immunity, Infection and Forensics', 'Describe how decomposers contribute to nutrient cycling.', 'Saprobionts (fungi, bacteria) secrete extracellular enzymes onto dead matter; soluble products absorbed by diffusion. Detritivores fragment material. Resulting NH4+ enters the nitrogen cycle; CO2 returns to atmosphere via respiration.', 14, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'List the four stages of aerobic respiration with location.', 'Glycolysis (cytoplasm), link reaction (matrix), Krebs cycle (matrix), oxidative phosphorylation (inner mitochondrial membrane / cristae).', 1, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Outline glycolysis.', 'Glucose phosphorylated using 2 ATP -> hexose bisphosphate -> 2 triose phosphate. Each TP oxidised to pyruvate; net 2 ATP and 2 NADH per glucose. Anaerobic; in cytoplasm.', 2, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Describe the link reaction and Krebs cycle.', 'Link: 2 pyruvate -> 2 acetyl-CoA, 2 NADH and 2 CO2. Krebs (x2): each acetyl-CoA + 4C -> 6C; decarboxylation/dehydrogenation give 2 CO2, 3 NADH, 1 FADH2 and 1 ATP per turn (per glucose: 4 CO2, 6 NADH, 2 FADH2, 2 ATP).', 3, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Explain oxidative phosphorylation by chemiosmosis.', 'NADH/FADH2 deliver e- to ETC on inner membrane. Electrons pass between carriers, pumping H+ into intermembrane space. H+ flows back through ATP synthase -> ATP. O2 final acceptor: O2 + 4H+ + 4e- -> 2H2O.', 4, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Compare lactate and ethanol fermentation.', 'Animals: pyruvate + NADH -> lactate + NAD+; reversible (lactate cleared in liver -> oxygen debt). Yeast/plants: pyruvate -> ethanal + CO2 -> ethanol + NAD+; irreversible. Both regenerate NAD+ to allow glycolysis to continue.', 5, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Compare slow- and fast-twitch muscle fibres.', 'Slow-twitch (Type I): aerobic, many mitochondria, lots of myoglobin, fatigue-resistant (postural muscles, marathon). Fast-twitch (Type II): anaerobic glycolysis, large glycogen and phosphocreatine stores, fatigue quickly (sprinting, weightlifting).', 6, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Describe the structure of a sarcomere.', 'Region between two Z-lines. Contains overlapping thin actin and thick myosin filaments. I-band: actin only. A-band: full length of myosin. H-zone: myosin only (no actin). M-line: middle of sarcomere. Sarcomere shortens during contraction.', 7, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Outline the sliding filament theory.', 'AP arrives at NMJ -> Ca2+ released from sarcoplasmic reticulum -> Ca2+ binds troponin, moving tropomyosin to expose actin binding sites. Myosin heads bind actin -> power stroke (ADP/Pi released). New ATP binds, head detaches; ATP -> ADP+Pi resets.', 8, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Describe how heart rate is controlled.', 'SAN sets pace -> wave of depolarisation across atria -> AVN delays -> Bundle of His -> Purkyne fibres -> ventricles contract from apex up. Medulla regulates rate via sympathetic (accelerator) and parasympathetic (vagus) nerves; baroreceptors and chemoreceptors feed back.', 9, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'How does exercise affect ventilation?', 'CO2 produced in respiration lowers blood pH; chemoreceptors in aortic / carotid bodies detect this and signal medulla -> increases breathing rate and depth. Stretch receptors in lungs prevent over-inflation. After exercise, debt repaid by elevated breathing.', 10, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Define VO2 max and how it adapts to training.', 'Maximum rate of O2 uptake during intense exercise (mL kg^-1 min^-1). Reflects cardiovascular and respiratory efficiency. Aerobic training raises VO2 max via increased stroke volume, capillary density, mitochondria and myoglobin in muscle.', 11, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Outline thermoregulation during exercise.', 'Increased respiration produces heat. Hypothalamus detects rise; vasodilation of skin arterioles, sweating (evaporative cooling), reduced metabolic heat. After exercise: shivering or vasoconstriction may follow if body T overshoots.', 12, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Describe how performance-enhancing drugs work and ethical issues.', 'Anabolic steroids: mimic testosterone -> increased muscle synthesis; risks include heart damage and infertility. EPO: boosts red blood cells -> O2 carriage; risk of clots. Stimulants: mask fatigue. Ethics: unfair advantage, health risk, role-model effect, legality.', 13, 'alevel'),
  ('Biology', 'Edexcel A', 'S7', 'Run for Your Life', 'Describe the keyhole / arthroscopic surgery for sports injury.', 'A small incision allows a fibre-optic camera and instruments into a joint. Cartilage tears are trimmed or repaired; ACL reconstruction uses graft tissue. Less tissue trauma -> faster recovery than open surgery, though possible complications (infection, stiffness).', 14, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Describe the structure of a typical neurone.', 'Cell body (with nucleus), dendrites (receive signals), axon (conducts AP), and axon terminals (release neurotransmitter). Axon may be myelinated by Schwann cells (PNS) or oligodendrocytes (CNS), with nodes of Ranvier.', 1, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Distinguish CNS and PNS, somatic and autonomic, sympathetic and parasympathetic.', 'CNS = brain + spinal cord. PNS: sensory + motor neurones. Somatic: voluntary skeletal muscle. Autonomic: involuntary smooth/cardiac muscle/glands. Sympathetic: fight/flight; parasympathetic: rest/digest.', 2, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Explain the resting potential.', 'Na+/K+ pump moves 3 Na+ out / 2 K+ in per ATP. K+ leaks out via leak channels, leaving inside ~-70 mV relative to outside. Maintained by ATP and selective membrane permeability.', 3, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Sketch and label an action potential.', 'Stimulus -> threshold (-55 mV) -> voltage-gated Na+ channels open (depolarisation to +40 mV). Na+ channels close, K+ channels open (repolarisation). Hyperpolarisation; Na+/K+ pump restores resting potential.', 4, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Why does myelination speed transmission?', 'Myelin (Schwann/oligodendrocyte) is electrically insulating. Action potentials only occur at unmyelinated nodes of Ranvier; the impulse "jumps" between nodes (saltatory conduction), much faster than continuous conduction.', 5, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Describe synaptic transmission at a cholinergic synapse.', 'AP arrives -> Ca2+ channels open, Ca2+ enters -> vesicles fuse with membrane and release ACh. ACh diffuses across cleft, binds postsynaptic receptors, opens Na+ channels. Acetylcholinesterase hydrolyses ACh; choline recycled.', 6, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Describe excitatory and inhibitory postsynaptic potentials.', 'EPSP: depolarising (Na+ entry) — moves potential towards threshold. IPSP: hyperpolarising (Cl- entry or K+ exit) — moves it away. Summation of EPSPs and IPSPs determines whether the postsynaptic neurone fires.', 7, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Describe the major regions of the human brain and their functions.', 'Cerebrum: voluntary action, learning, memory. Cerebellum: balance, coordination. Hypothalamus: homeostasis, thermoregulation. Pituitary: hormones. Medulla: heart and breathing centres.', 8, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Outline how the eye detects light.', 'Light is refracted mainly by the cornea, with fine focusing by the lens, and is focused on the retina. In a rod, light breaks rhodopsin into retinal and opsin; this closes cation (Na+) channels, so the rod hyperpolarises and stops releasing the neurotransmitter that inhibits the bipolar cell. The bipolar cell then depolarises and stimulates a ganglion cell, which fires action potentials along the optic nerve (optic neurones) to the visual cortex. Cones (3 types, concentrated in the fovea) work in a similar way and give colour vision.', 9, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Compare rods and cones.', 'Rods: high sensitivity (many to one bipolar -> retinal convergence); monochromatic; rhodopsin; concentrated outside fovea. Cones: low sensitivity, high acuity (1:1 to bipolar); iodopsin (3 colour types); concentrated in fovea.', 10, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Outline learning and types of memory.', 'Sensory -> short-term -> long-term (consolidation). Habituation: decreased response to a repeated harmless stimulus (sea-slug Aplysia). Classical and operant conditioning. Memories stored across synapses; LTP strengthens connections.', 11, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Describe how drugs affect synapses (e.g. nicotine, MDMA, L-DOPA).', 'Nicotine: agonist of nicotinic ACh receptors -> stimulation; reward via dopamine. MDMA: floods synapses with serotonin (release + reuptake inhibition). L-DOPA: precursor of dopamine, crosses BBB to relieve Parkinson''s symptoms.', 12, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Describe the symptoms and cause of Parkinson''s disease.', 'Loss of dopaminergic neurones in the substantia nigra. Symptoms: tremor, rigidity, bradykinesia, postural instability. Treatments: L-DOPA, dopamine agonists, MAO-B inhibitors, deep brain stimulation. Causes: idiopathic, genetic factors, environmental.', 13, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Outline the imaging techniques: CT, MRI, fMRI, PET.', 'CT: X-ray slices -> structural images. MRI: magnetic field aligns nuclei -> high-resolution structural images, no ionising radiation. fMRI: detects blood-O2 changes (BOLD signal) -> activity. PET: radiolabelled tracers -> functional metabolism.', 14, 'alevel'),
  ('Biology', 'Edexcel A', 'S8', 'Grey Matter', 'Compare nature and nurture in shaping the brain.', 'Genes provide the basic neural framework (e.g. innate reflexes). Environment shapes synaptic connections, particularly in critical periods (e.g. visual deprivation in kittens). Both interact: brain plasticity allows learning throughout life.', 15, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP1: investigate the effect of caffeine on heart rate in Daphnia.', 'Daphnia on a cavity slide under cotton wool strands, low power. Acclimatise 2 min; count beats in 20 s (x3 = bpm), three counts, mean. Add caffeine drops, wait 2 min, recount. Fresh Daphnia per concentration. IV: caffeine concentration (e.g. 0-0.5%); DV: heart rate (bpm); control temperature (LED light), acclimatisation time, volume added, Daphnia size. Ethics: fewest organisms, sub-lethal doses, minimal time on slide, return to pond water. Analysis: plot mean bpm vs concentration (positive correlation); Spearman''s rank. Caffeine inhibits phosphodiesterase, so cAMP stays high.', 1, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP2: investigate the vitamin C content of food and drink.', 'Pipette 1 cm³ DCPIP (blue) into a tube; add juice drop by drop from a burette or graduated pipette, swirling, against a white tile, until it turns colourless. Record volume; 3 repeats. Repeat with known ascorbic acid concentrations to make a calibration curve. IV: juice type or treatment (fresh, pasteurised, boiled); DV: volume to decolourise; control DCPIP volume and concentration, temperature, rate of addition. Safety: DCPIP stains, so gloves and eye protection. Analysis: less juice needed = more vitamin C; read concentration off the calibration curve by interpolation.', 2, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP3: investigate membrane permeability (effect of temperature or alcohol concentration).', 'Cut equal beetroot cylinders with a cork borer, trim to 1 cm; rinse in distilled water until clear. One per tube with 5 cm³ distilled water, 20 min in water baths at 20-70°C (or in 0-50% ethanol at one temperature). Remove beetroot, shake, read absorbance with a blue-green filter (~530 nm), zeroed with water. IV: temperature or ethanol %; DV: absorbance; control cylinder size, water volume, time. Safety: cut away from the body on a tile; tongs for hot tubes. Analysis: absorbance low to ~40°C then rises sharply as proteins denature and the bilayer becomes more fluid; ethanol disrupts the bilayer.', 3, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP4: investigate the effect of enzyme and substrate concentrations on the initial rate of reaction.', 'Catalase (equal-mass potato discs or fixed volume of liver homogenate) in a flask at 25°C. Add pre-warmed H₂O₂, bung at once, record O₂ in a gas syringe every 30 s for 5 min; 3 repeats. Vary H₂O₂ concentration (0.5-8%), or vary enzyme amount with substrate fixed. Control temperature, volumes, enzyme mass. Safety: H₂O₂ irritant, eye protection and gloves; no naked flames. Analysis: initial rate = gradient of tangent at t = 0. Rate vs [substrate] rises then plateaus at Vmax (active sites saturated); rate vs [enzyme] is proportional while substrate is in excess.', 4, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP5: prepare and stain a root tip squash to observe the stages of mitosis.', 'Cut 5 mm garlic or onion root tips; 1 mol dm⁻³ HCl at 55-60°C for ~5 min (fixes cells, breaks down the middle lamella). Rinse, keep only the terminal 1-2 mm (meristem). Add toluidine blue or acetic orcein, macerate, wait 2 min. Coverslip, filter paper, press firmly and vertically (no twisting) to give one cell layer. Find small square cells on low power; count cells in each stage on high power. Safety: HCl irritant, eye protection. Analysis: mitotic index = cells in mitosis ÷ total cells; time in a stage = proportion of cells x cycle time.', 5, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP6: identify sclerenchyma fibres, phloem sieve tubes and xylem vessels and their location in stems.', 'Cut very thin transverse sections of celery petiole or sunflower stem with a razor blade on a tile; keep in water. Stain in toluidine blue ~1 min, rinse, mount in water. Low power: draw a plan (tissue outlines only). High power: identify tissues. Xylem: towards the centre of each bundle, large empty lignified cells (blue-green). Phloem: outside the xylem, small thin-walled cells, no lignin (purple). Sclerenchyma: cap outside the phloem, very thick lignified walls, narrow lumen (blue-green). Safety: razor blades, cut away from fingers; stain gloves. Measure cells with a calibrated eyepiece graticule.', 6, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP7: investigate plant mineral deficiencies.', 'Grow equal numbers of similar duckweed plants (or seedlings) in equal volumes of culture solutions: complete, lacking nitrate, lacking magnesium, lacking calcium, plus distilled water. Cover containers, wrap in foil, same light and temperature; at least 3 replicates. Count fronds and note colour every few days for 2-3 weeks; weigh at the end. IV: solution; DV: frond number, colour, mass. Safety: low hazard, wash hands; keep light banks away from water. Analysis: complete solution grows most; no nitrate or Mg²⁺ gives yellow (chlorotic) fronds and less growth; compare means with a t-test.', 7, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP8: determine the tensile strength of plant fibres.', 'Extract single fibres (e.g. celery strings) carefully. Measure diameter at several points (calibrated graticule or callipers); A = πr². Clamp one end, hang a hook, add masses in 10 g steps, waiting ~10 s each, until it breaks. Test at least 10 fibres per type. Safety: tray or cushion under the masses; eye protection in case the fibre snaps and recoils. Analysis: force F = m (kg) x 9.81; tensile stress = F ÷ A (Pa or MPa). Compare species or plant parts; relate strength to cellulose microfibrils, secondary wall thickening and lignin. Report SD and range.', 8, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP9: investigate the antimicrobial properties of plants, including aseptic technique.', 'Grind equal masses of plants (e.g. garlic, mint) with equal volumes of ethanol; filter. Aseptically spread a non-pathogenic bacterium (e.g. Bacillus subtilis) as a lawn on nutrient agar. Soak sterile paper discs in each extract, let the ethanol evaporate, place on the agar with an ethanol-only control disc. Tape lid with two strips, incubate upside down at 25°C for 48 h. IV: plant extract; DV: area of clear zone. Safety: ethanol is highly flammable, keep away from the Bunsen; never open plates after incubation; autoclave before disposal. Analysis: area = πr²; compare means; the control should show no zone.', 9, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP10: ecology of a habitat using quadrats and transects, including abiotic factors.', 'Random sampling: two tapes at right angles make a grid; random coordinates; record count, percentage cover or ACFOR in each quadrat (10-30 quadrats). Transect along a gradient: quadrats at regular intervals (e.g. every 2 m); at each point measure light, temperature, soil moisture, pH at the same time of day; repeat 3 parallel transects. Safety: fieldwork risk assessment (terrain, water, weather), wash hands. Analysis: kite diagram of abundance with abiotic readings; Spearman''s rank to test for correlation; index of diversity D = N(N−1) ÷ Σn(n−1).', 10, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP11: investigate photosynthesis using isolated chloroplasts (the Hill reaction).', 'Blend spinach in ice-cold, isotonic, buffered isolation medium; filter through muslin; centrifuge at low then higher speed to pellet chloroplasts; resuspend and keep on ice in dim light. Mix equal volumes of chloroplast suspension and DCPIP; place at different distances from a lamp. Time loss of blue colour (or read absorbance with a red filter). Controls: tube in foil (dark); DCPIP with no chloroplasts. Control temperature (heat shield). Safety: DCPIP harmful, eye protection; balance the centrifuge. Analysis: rate = 1/time vs light intensity (∝ 1/d²); DCPIP replaces NADP as electron acceptor.', 11, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP12: investigate the effect of temperature on the initial rate of an enzyme-catalysed reaction, including Q₁₀.', 'Amylase and 1% starch in separate tubes in a water bath (20-60°C) for 5 min to equilibrate. Mix, start the stopwatch; every 30 s put a drop on iodine on a spotting tile. End-point: iodine stays yellow-brown (no starch). 3 repeats per temperature. IV: temperature; DV: time to end-point; control volumes, concentrations, pH. Safety: tongs for hot water baths; iodine stains, gloves. Analysis: rate = 1/t; bell-shaped curve with an optimum; above it the enzyme denatures. Q₁₀ = rate at (T + 10)°C ÷ rate at T°C, about 2 below the optimum.', 12, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP13: investigate the effect of temperature on the development of organisms.', 'Brine shrimp: equal volumes of artificial sea water at a range of temperatures (e.g. 10-30°C); add the same mass of cysts (e.g. 0.05 g), same light. Every 12-24 h stir gently, remove a fixed volume, count hatched larvae, return them. Continue 2-3 days; 3 repeats. Alternative: mean seedling shoot growth per day. IV: temperature; DV: number hatched (or growth rate); control cyst mass, salt concentration, light. Ethics and safety: treat shrimp with respect, small numbers; keep electrics away from water. Analysis: rate rises to an optimum then falls; Q₁₀; discuss links to climate change and limits of lab data.', 13, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP14: use gel electrophoresis to separate DNA fragments of different length.', 'Agarose gel in a tank with wells at the negative (cathode) end, covered in buffer. Mix restriction-digested DNA with loading dye and micropipette a fixed volume into each well without piercing it; include a DNA ladder. Lid on, run at low voltage until the dye front is near the end. Switch off, stain (e.g. methylene blue), measure well-to-band distances. Safety: only switch on with the lid on, disconnect before touching; gloves. Analysis: DNA is negative (phosphate) so moves to the anode; shorter fragments move further; size unknowns from a ladder calibration curve.', 14, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP15: investigate the effect of different antibiotics on bacteria.', 'Aseptically spread a non-pathogenic bacterium (e.g. E. coli K-12) evenly as a lawn on nutrient agar. With flamed forceps press antibiotic discs (or a multidisc) onto the agar, at least 25 mm apart. Tape lid with two strips (not sealed), label the base, incubate upside down at 25°C or below for 24-48 h. Measure zone diameters through the base without opening. IV: antibiotic; DV: area of zone of inhibition. Safety: never open plates after incubation; autoclave before disposal. Analysis: area = πr²; bigger zone = more effective (or better diffusion); cannot tell bactericidal from bacteriostatic.', 15, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP16: investigate rate of respiration.', 'Respirometer: soda lime at the bottom of each tube, cotton wool above, then germinating seeds; control tube with an equal volume of glass beads. Connect to a capillary with a coloured fluid drop; water bath, equilibrate 5 min. Record drop position every minute for 10-15 min; repeat at different temperatures. IV: temperature; DV: distance moved per minute. Safety: soda lime is corrosive, gloves and eye protection; keep it away from organisms. Analysis: soda lime absorbs CO₂, so movement shows O₂ uptake; volume = πr² x distance; subtract control; rate rises with temperature (Q₁₀ ≈ 2) until enzymes denature.', 16, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP17: investigate the effects of exercise on tidal volume, breathing rate, minute ventilation and O₂ consumption using spirometer traces.', 'Screen participants and get consent. With a nose clip and clean mouthpiece, record a spirometer trace at rest (spirometer filled with medical-grade O₂, fresh soda lime). Do standard exercise (e.g. step-ups to a metronome for 5 min); record immediately after and every minute in recovery. From the trace: tidal volume = trough-to-peak height; breathing rate = peaks per minute; minute ventilation = tidal volume x breathing rate; O₂ consumption = fall in trace volume per minute (soda lime removes CO₂). Safety: stop if dizzy or unwell. Analysis: all increase after exercise, as chemoreceptors detect raised CO₂.', 17, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Outline CP18: investigate habituation to a stimulus.', 'Snail on a damp surface, left until tentacles are fully out. Touch gently between the upper tentacles with a damp cotton bud; start the stopwatch; time until tentacles fully re-emerge. Repeat at the same place and pressure 10-15 times; repeat with other snails. IV: number of touches; DV: re-emergence time; control touch strength and position, interval, temperature, light, noise. Ethics: gentle touch, keep snails moist, fewest snails, return them. Analysis: plot mean time vs touch number; time falls; Spearman''s rank. Habituation: fewer Ca²⁺ channels open presynaptically, less neurotransmitter released.', 18, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Practical skills: how is a calibration curve made and used?', 'Measure the same quantity for a series of solutions of known concentration (e.g. volume of ascorbic acid standard needed to decolourise 1 cm³ DCPIP in CP2, or a DNA ladder''s band distances in CP14). Plot the known values and draw a line or curve of best fit. Measure the unknown sample in exactly the same way, then read its value off the curve by interpolation. Keep conditions (volumes, temperature, filter, gel and run time) the same for standards and unknowns. Only read values within the range of the standards.', 19, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Practical skills: why calculate standard deviation, and which statistical test fits which data?', 'Standard deviation measures the spread of repeat readings around the mean; a small SD means the data are more consistent (precise), and overlapping mean ± SD suggests a difference may not be significant. Report it with means (e.g. heart rates in CP1, fibre strength in CP8). Tests: Spearman''s rank for a correlation between two variables (CP1, CP10, CP18); a t-test to compare two means of normally distributed data (CP7); Mann-Whitney U to compare two groups otherwise. Compare the calculated value with the critical value at p = 0.05.', 20, 'alevel'),
  ('Biology', 'Edexcel A', 'CP', 'Core Practicals', 'Practical skills: how is an eyepiece graticule calibrated and used to measure cells?', 'Put a stage micrometer (known divisions, e.g. 10 μm) on the stage and line its scale up with the eyepiece graticule. Count how many eyepiece units match a known stage distance; length of 1 eyepiece unit = stage distance ÷ number of units. Recalibrate for every objective lens. Replace with the specimen, measure in eyepiece units and multiply by the calibrated value (e.g. xylem and sclerenchyma diameter in CP6, fibre diameter in CP8). Measure several cells and take a mean.', 21, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'What happens in a condensation reaction and in a hydrolysis reaction?', 'Condensation joins two molecules with a new covalent bond and releases a molecule of water. Hydrolysis breaks a covalent bond by adding a molecule of water. Glycosidic, ester, peptide and phosphodiester bonds are all made by condensation and broken by hydrolysis.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'How do α-glucose and β-glucose differ?', 'Both are hexoses with the formula C₆H₁₂O₆. The only difference is at carbon 1: in α-glucose the –OH points below the ring; in β-glucose it points above the ring. α-glucose builds starch and glycogen; β-glucose builds cellulose.', 2, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'Which monosaccharides make maltose, sucrose and lactose?', 'Maltose: glucose + glucose (α-1,4 glycosidic bond). Sucrose: glucose + fructose. Lactose: galactose + glucose. Each is formed by one condensation reaction that releases one water molecule.', 3, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'Compare starch and glycogen.', 'Both are insoluble α-glucose polymers with α-1,4 and α-1,6 glycosidic bonds, used as compact energy stores that do not affect water potential. Starch (amylose + amylopectin) is the plant store; glycogen is the animal store and is more highly branched, with more chain ends, so glucose can be released faster.', 4, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'How does the structure of cellulose give it high tensile strength?', 'Straight, unbranched β-glucose chains (alternate units inverted) lie parallel. Their –OH groups form many hydrogen bonds between neighbouring chains, which group into microfibrils and fibres. The huge number of hydrogen bonds makes the cell wall strong.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'How is a triglyceride formed?', 'One glycerol and three fatty acids join in three condensation reactions between glycerol –OH groups and fatty acid carboxyl groups. Three water molecules are released and three ester bonds form.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'Why are triglycerides a good energy store?', 'Their long hydrocarbon chains have many C–H bonds, so they release about twice as much energy per gram as carbohydrate. They are insoluble, so they do not affect water potential, and they are stored without water, making a light, compact store.', 7, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'How are phospholipids suited to forming cell membranes?', 'The charged phosphate head is hydrophilic and the two fatty acid tails are hydrophobic. In water they form a bilayer with heads facing outwards and a hydrophobic core that blocks ions and polar molecules, making the membrane partially permeable. The molecules can move sideways, so the membrane is fluid.', 8, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'What bonds hold the tertiary structure of a protein?', 'Hydrogen bonds (weak but numerous, between polar R groups), ionic bonds (between oppositely charged R groups, sensitive to pH) and disulfide bonds (strong covalent S–S bonds between cysteine R groups). Hydrophobic R groups also cluster together away from water.', 9, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'How is the structure of collagen related to its function?', 'Three polypeptide chains form a triple helix held by many hydrogen bonds. Glycine at every third position lets the chains pack tightly. Covalent cross-links join staggered molecules into fibrils and fibres with no weak points, giving high tensile strength in tendons, skin and artery walls.', 10, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'How is the structure of haemoglobin related to its function?', 'A globular protein of four chains (two α, two β), each with a haem group containing Fe²⁺ that binds one O₂. Hydrophilic R groups face outwards, making it soluble. Binding of one O₂ changes the shape so more bind easily (cooperative binding).', 11, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'Describe semi-conservative DNA replication.', 'DNA helicase breaks the hydrogen bonds between bases and the strands separate. Free nucleotides pair with complementary bases on each template. DNA polymerase joins them with phosphodiester bonds; DNA ligase joins short sections. Each new molecule has one old and one new strand.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'How do mRNA and tRNA differ in structure?', 'mRNA is a single, largely linear strand carrying codons from the nucleus to the ribosome. tRNA is a short single strand folded into a clover-leaf shape held by hydrogen bonds between bases in the same strand, with an anticodon at one end and an amino acid attachment site at the other.', 13, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'What are the main features of the genetic code?', 'Triplet: three bases (a codon) code for one amino acid, giving 64 codons. Start codon AUG; stop codons UAA, UAG and UGA. Degenerate: most amino acids have more than one codon. Non-overlapping: each base is read in only one triplet. Much of the genome does not code for proteins.', 14, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'How does a single substitution cause sickle cell anaemia?', 'In the β-globin gene, GAG becomes GTG (mRNA GUG), so glutamic acid at position 6 becomes valine. Valine''s non-polar R group forms a hydrophobic patch, so at low oxygen haemoglobin molecules stick into fibres, making red blood cells rigid and sickle-shaped.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'What is the induced fit hypothesis?', 'The active site is not a rigid, exact match for the substrate. When a complementary substrate binds, the active site changes shape slightly to mould around it, straining substrate bonds and lowering the activation energy. After the products are released, the active site returns to its original shape.', 16, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'Compare competitive and non-competitive inhibition.', 'Competitive: inhibitor resembles the substrate and binds the active site; more substrate reduces the inhibition. Non-competitive: inhibitor binds an allosteric site and changes the active site''s shape; more substrate has no effect and the maximum rate is lowered.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '1', 'Biological Molecules', 'Why do plants need nitrate, calcium, magnesium and phosphate ions?', 'Nitrate: nitrogen to make amino acids and the bases of DNA. Calcium: calcium pectate in the middle lamella that holds cells together. Magnesium: to make chlorophyll. Phosphate: to make ADP and ATP.', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'What does cell theory state?', 'All living organisms are made of one or more cells; the cell is the basic unit of structure, function and organisation; new cells arise only by division of existing cells. Viruses are not cells, so they sit outside cell theory.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'List the main structures of a prokaryotic cell.', 'Peptidoglycan cell wall, cell surface membrane, cytoplasm with 70S ribosomes, circular DNA in a nucleoid (no membrane, no histones) and plasmids. Some species also have a capsule, flagella and pili. There are no membrane-bound organelles.', 2, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'How does the Gram stain distinguish bacteria?', 'Crystal violet and iodine form a complex; alcohol washes it out of Gram negative cells (thin peptidoglycan plus outer membrane), which then take up red safranin and look pink. Gram positive cells keep the complex in their thick peptidoglycan and look purple.', 3, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Why is penicillin less effective against Gram negative bacteria?', 'Penicillin stops peptidoglycan cross-links forming, so growing cells burst by osmotic lysis. In Gram negative bacteria the outer membrane (with lipopolysaccharide) keeps penicillin away from the thin peptidoglycan layer.', 4, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Give the functions of the nucleolus, RER, SER and Golgi apparatus.', 'Nucleolus: makes rRNA and assembles ribosome subunits. RER: proteins made on its ribosomes are folded and transported. SER: makes lipids, including phospholipids and steroids. Golgi: modifies proteins (e.g. adds carbohydrate), packages them into vesicles, makes lysosomes.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Give the functions of lysosomes, centrioles and the tonoplast.', 'Lysosomes: single-membrane vesicles of hydrolytic enzymes that digest engulfed material and worn-out organelles. Centrioles: organise spindle fibres in animal cells. Tonoplast: partially permeable membrane controlling movement into and out of the vacuole.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Magnification and resolution: definitions and formula', 'Magnification = image size ÷ actual size. Resolution = the smallest distance between two points that can still be seen as separate. Light microscope resolution is about 200 nm; TEM about 0.5 nm, because electrons have a much shorter wavelength than light. 1 mm = 1000 μm; 1 μm = 1000 nm.', 7, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'How is an eyepiece graticule calibrated?', 'Line up the graticule with a stage micrometer of known divisions (e.g. 10 μm). Find how many eyepiece divisions match a known length, then divide. Example: 25 divisions = 100 μm, so 1 division = 4 μm. Recalibrate for every objective lens.', 8, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Name the nucleic acid and structure of the four example viruses.', 'λ phage: dsDNA, head and tail, infects E. coli. Tobacco mosaic virus: ssRNA, helical rod, no envelope. Ebola: ssRNA, filamentous, enveloped. HIV: ssRNA retrovirus with reverse transcriptase, enveloped, infects helper T cells.', 9, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Lytic cycle vs latency', 'Lytic: attachment to receptors, entry of nucleic acid, host machinery copies the genome and makes viral proteins, assembly, then lysis releases new viruses. Latency: the viral genome stays in the host (prophage in λ, provirus in HIV) with no new viruses made, until a trigger starts the lytic cycle.', 10, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Why can antibiotics not treat viruses, and how do antivirals work?', 'Viruses are not cells: no cell wall, no 70S ribosomes and no metabolism for antibiotics to target. Antivirals must inhibit replication by blocking a step unique to the virus, e.g. reverse transcriptase or protease inhibitors for HIV.', 11, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'How was the spread of Ebola controlled in 2014?', 'Isolation of patients and quarantine of contacts; contact tracing for the 21-day incubation period; protective equipment and decontamination for health workers; safe burial teams; public education and screening of travellers. Prevention was the focus because no licensed drug or vaccine existed.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Stages of the cell cycle and what happens to DNA', 'Interphase: G1 (growth), S (DNA replicated, each chromosome becomes two sister chromatids), G2 (growth, preparation). Then mitosis and cytokinesis. DNA content doubles in S phase and is halved again by mitosis; chromosome number stays 2n.', 13, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Stages of mitosis', 'Prophase: chromosomes condense, nuclear envelope breaks down, spindle forms. Metaphase: chromosomes line up singly at the equator. Anaphase: centromeres divide, chromatids pulled to poles. Telophase: nuclear envelopes reform. Cytokinesis: cleavage furrow (animals) or cell plate (plants).', 14, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'How does meiosis produce genetic variation?', 'Crossing over in prophase I: non-sister chromatids exchange sections at chiasmata, giving new allele combinations. Independent assortment in metaphase I: homologous pairs orient randomly, giving 2ⁿ combinations (2²³ ≈ 8.4 million in humans). Random fertilisation adds more.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Non-disjunction: Down''s and Turner''s syndromes', 'Non-disjunction is failure of homologous chromosomes (anaphase I) or sister chromatids (anaphase II) to separate, giving n + 1 and n − 1 gametes. Down''s syndrome: trisomy 21 (47 chromosomes, polysomy). Turner''s syndrome: 45,X (monosomy).', 16, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Events of fertilisation in mammals, in order', 'Capacitation; sperm passes follicle cells; binds zona pellucida; acrosome reaction releases enzymes that digest the zona; sperm and oocyte membranes fuse; cortical reaction hardens the zona to stop polyspermy; oocyte completes meiosis II; haploid nuclei fuse to form a diploid zygote.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '2', 'Cells, Viruses and Reproduction of Living Things', 'Pollen tube growth and double fertilisation', 'Pollen germinates on the stigma; the tube grows down the style, secreting digestive enzymes, controlled by the tube nucleus. The generative nucleus divides by mitosis into two male nuclei. One fuses with the egg (diploid zygote); the other fuses with two polar nuclei (triploid endosperm).', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'What are the eight taxonomic ranks, from largest to smallest?', 'Domain, kingdom, phylum, class, order, family, genus, species. Each rank is nested inside the one above; moving down, groups contain fewer organisms that share more features and a more recent common ancestor.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'How is a binomial name written?', 'Genus name with a capital letter, then specific name in lower case, e.g. Homo sapiens. Italicised when printed, underlined when handwritten. Everyone worldwide uses the same name for the same species.', 2, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'What is the biological definition of a species?', 'A group of organisms with similar features that can interbreed in natural conditions to produce fertile offspring. Horses and donkeys are separate species because their offspring (mules) are almost always sterile.', 3, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'What are the main limitations of the biological species definition?', 'It cannot be applied to asexual organisms or fossils; geographically separated populations never meet, so interbreeding cannot be tested; some separate species form fertile hybrids (e.g. wolves and coyotes); ring species have no clear dividing line; ''similar features'' is vague.', 4, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'Why is it often hard to assign organisms to a species?', 'Speciation is gradual; variation within a species; cryptic species look alike but are genetically distinct (e.g. savanna and forest elephants); convergent evolution makes unrelated organisms look similar; few specimens; most microbes cannot be cultured; taxonomists disagree.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'How does gel electrophoresis separate DNA fragments?', 'DNA is cut with restriction enzymes and loaded into wells in agarose gel. A voltage is applied; the negatively charged phosphate groups make DNA move towards the anode (+). Smaller fragments move further. A ladder estimates sizes; stain or dye shows the bands.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'How can electrophoresis banding patterns show relationships?', 'Samples sharing more bands are likely to be more closely related; an unknown with the same bands as a known species is probably that species. Limitation: it compares fragment lengths only, so same-length fragments may differ in sequence.', 7, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'How do DNA sequencing and bioinformatics show evolutionary relationships?', 'The same gene is sequenced in each species; software aligns sequences and counts base differences. Mutations build up over time, so fewer differences means a more recent common ancestor. Results give phylogenetic trees and, with a constant rate, a molecular clock.', 8, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'Why use rRNA genes for distant groups but mitochondrial genes for close species?', 'rRNA genes are in every cellular organism and change slowly, so they suit very distant comparisons. Mitochondrial genes such as cytochrome oxidase I change faster, so they separate closely related species (DNA barcoding).', 9, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'What do journals, peer review and conferences do for new evidence?', 'Journals publish methods and data so others can reproduce the work. Peer review: other experts check validity, conclusions and originality before publication (reduces flawed work, cannot prove conclusions true). Conferences: findings are presented, questioned and discussed.', 10, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'What evidence supports the three-domain model?', 'Woese''s rRNA comparisons: archaea differ from bacteria as much as either does from eukaryotes. Archaea have branched ether-linked membrane lipids, no peptidoglycan, histones, eukaryote-like RNA polymerase, and are not inhibited by streptomycin.', 11, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'What are the three domains and the five kingdoms?', 'Domains: Bacteria, Archaea, Eukarya. Kingdoms: Prokaryotae, Protoctista, Fungi, Plantae, Animalia. The five-kingdom model put all prokaryotes in one kingdom, which hides the large differences between bacteria and archaea.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'Outline how natural selection causes evolution.', 'Variation exists, partly genetic (new alleles by mutation). More offspring are produced than survive, so there is competition and selection pressure. Individuals with advantageous alleles survive and reproduce more, passing them on, so allele frequency increases over generations.', 13, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'What is a niche, and what are the three types of adaptation?', 'Niche: the role of a species in its habitat (food, predators, activity times, tolerated conditions). Anatomical: structure (marram grass rolled leaves). Physiological: body processes (kangaroo rat concentrated urine). Behavioural: actions (nocturnal activity).', 14, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'Compare allopatric and sympatric speciation.', 'Both need reproductive isolation so gene flow stops, then mutations, selection and drift change allele frequencies separately. Allopatric: geographical barrier (Galápagos finches). Sympatric: same area, e.g. polyploidy (Spartina anglica), ecological isolation (apple maggot flies), behaviour or timing.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'Why is there an evolutionary race between pathogens and medicines?', 'Each drug is a selection pressure. Resistant mutants already present survive and multiply, so resistance allele frequency rises (plasmids spread it between bacteria). Examples: MRSA, multidrug-resistant TB, HIV, chloroquine-resistant Plasmodium. New drugs must keep being developed.', 16, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'How is the index of diversity calculated and interpreted?', 'D = N(N − 1) / Σn(n − 1), where N = total organisms of all species and n = organisms of one species. Minimum 1 (one species); higher D means greater diversity. It accounts for both species richness and evenness. Genetic diversity = variety of alleles in the gene pool.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '3', 'Classification and Biodiversity', 'Compare zoos, seed banks and protected habitats.', 'Zoos (ex situ): captive breeding, studbooks, reintroduction; but small gene pools, lost wild skills. Seed banks (ex situ): dried, about −20 °C, cheap and compact; but some seeds cannot be stored and do not evolve. Protected habitats (in situ): whole ecosystem, natural behaviour; but hard to police, fragmented.', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Why do larger organisms need specialised exchange surfaces and a mass transport system?', 'As size increases, volume rises faster than surface area, so SA:V falls. The body surface cannot supply enough O₂ for the volume of respiring tissue, and distances to inner cells are too long for diffusion. Exchange surfaces give a large area and short distance; mass transport carries substances in bulk between them and the tissues, keeping gradients steep.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Describe the fluid mosaic model of the cell surface membrane.', 'A phospholipid bilayer: hydrophilic heads face outwards, hydrophobic tails inwards. Fluid: phospholipids and many proteins move sideways. Mosaic: proteins scattered through it, including channel and carrier proteins that span the bilayer and extrinsic proteins on one surface. Glycoproteins and glycolipids act as receptors and recognition sites; cholesterol regulates fluidity.', 2, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Compare diffusion, facilitated diffusion, osmosis and active transport.', 'Diffusion: passive, down a concentration gradient, through the bilayer (small non-polar molecules). Facilitated diffusion: passive, down a gradient, through channel or carrier proteins (ions, glucose). Osmosis: passive net movement of water from higher to lower water potential through a partially permeable membrane. Active transport: against a gradient, via carrier proteins, using ATP.', 3, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'How do size, solubility and charge affect how a molecule crosses a membrane?', 'Small, non-polar or lipid-soluble (O₂, CO₂, steroids): simple diffusion through the bilayer. Small polar (water): slowly through the bilayer, fast through aquaporins. Ions: repelled by the hydrophobic core, so need channels or carriers. Larger polar molecules (glucose, amino acids): carrier proteins. Very large molecules and particles: vesicles (endocytosis, exocytosis).', 4, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'What is the equation for water potential, and how is it used?', 'ψ = P + π. Turgor pressure (P) is usually positive in a turgid plant cell and zero in a flaccid one; osmotic potential (π) is zero for pure water and negative for solutions. Example: P = 250 kPa, π = −600 kPa gives ψ = −350 kPa. Water moves from the higher (less negative) to the lower water potential.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Explain the role of ATP in active transport.', 'The ion or molecule binds to a carrier protein. ATP is hydrolysed to ADP + Pi, releasing energy; the phosphate attaches to the carrier, which changes shape and releases the substance on the other side, against its gradient. Energy is needed to phosphorylate ADP back to ATP, using energy from respiration. Example: the Na⁺/K⁺ pump moves 3 Na⁺ out and 2 K⁺ in per ATP.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'How are fish gills adapted for gas exchange?', 'Many gill filaments covered in lamellae give a large surface area. Thin lamella epithelium and dense capillaries give a short diffusion distance. Water is pumped over the gills in one direction. Countercurrent flow: blood flows opposite to the water, so it always meets water with more O₂ and a gradient is kept along the whole lamella (up to about 80% of O₂ extracted).', 7, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'How is the insect tracheal system adapted for gas exchange?', 'Air enters through spiracles, which can close to reduce water loss. Tracheae, held open by chitin rings, branch into fine tracheoles that reach individual respiring cells, so O₂ diffuses straight in and no blood transport is needed. In intense activity, lactate draws fluid out of the tracheole ends by osmosis, so air reaches further. Larger insects ventilate by abdominal pumping.', 8, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'How does gas exchange happen in a flowering plant leaf and stem?', 'Gases diffuse through stomata (opened when guard cells take up K⁺ and water and become turgid) into air spaces in the spongy mesophyll, dissolving in the water on moist cell walls. In light, photosynthesis uses CO₂ faster than respiration makes it, so CO₂ enters and O₂ leaves; in the dark this reverses. Lenticels in bark let gases reach living tissue beneath the cork.', 9, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Describe the cardiac cycle and the valve movements.', 'Atrial systole: atria contract, pushing blood through the open AV valves. Ventricular systole: ventricular pressure exceeds atrial pressure, so AV valves close; when it exceeds arterial pressure, semilunar valves open and blood is ejected. Diastole: ventricles relax; semilunar valves close when ventricular pressure falls below arterial pressure, AV valves open when it falls below atrial pressure.', 10, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'How is the heartbeat initiated and coordinated?', 'Cardiac muscle is myogenic. The SAN in the right atrium sends out a wave of excitation across the atria (atrial systole). Non-conducting tissue blocks direct spread; the AVN delays the wave by about 0.1 s so the atria empty first. It passes down the bundle of His to the apex, then up the Purkinje fibres, so the ventricles contract from the apex upwards.', 11, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'What do the parts of a normal ECG show, and how is heart rate found?', 'P wave: atrial depolarisation. QRS complex: ventricular depolarisation (large because the ventricles have more muscle). T wave: ventricular repolarisation. Heart rate = 60 / R–R interval in seconds; an interval of 0.8 s gives 75 beats per minute.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Describe the sequence of events in blood clotting.', 'Damage exposes collagen; platelets stick to it and each other, forming a plug. Platelets and damaged tissue release clotting factors, including thromboplastin. Thromboplastin (with Ca²⁺) converts prothrombin into thrombin. Thrombin converts soluble fibrinogen into insoluble fibrin, which forms a mesh that traps platelets and red blood cells to form a clot.', 13, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Outline the stages of atherosclerosis and its effects on health.', 'Endothelium damaged (e.g. high blood pressure, smoking) → inflammatory response; white cells enter the wall → cholesterol from LDLs builds up beneath the endothelium → calcium salts and fibrous tissue form a hard plaque that narrows the lumen and reduces elasticity. Plaques can trigger a thrombus, causing angina, myocardial infarction, stroke or aneurysm.', 14, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Explain the shape of the oxygen dissociation curve and the Bohr effect.', 'Sigmoid because binding is cooperative: once the first O₂ binds, haemoglobin changes shape and more O₂ binds easily. Flat at high pO₂ (lungs, full loading); steep at the pO₂ of tissues, so a small fall releases a lot of O₂. Bohr effect: more CO₂ forms H⁺, which lowers affinity and shifts the curve right, so more O₂ is unloaded in active tissues.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Compare haemoglobin, myoglobin and fetal haemoglobin.', 'Haemoglobin: four chains and four haem groups, cooperative binding, sigmoid curve, Bohr effect; transports O₂ in red blood cells. Myoglobin: one chain and one haem, hyperbolic curve far to the left; stores O₂ in muscle and releases it at very low pO₂. Fetal haemoglobin: higher affinity than adult (curve to the left), so it loads O₂ at the low pO₂ of the placenta.', 16, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'How is tissue fluid formed, reabsorbed and drained?', 'Arterial end: hydrostatic pressure > oncotic pressure, so water and small solutes are forced out through gaps in the capillary wall (proteins stay in). Hydrostatic pressure falls along the capillary. Venous end: oncotic pressure > hydrostatic pressure, so water returns by osmosis. Excess fluid drains into lymph capillaries as lymph and returns to the blood in veins near the heart.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '4', 'Exchange and Transport', 'Compare the structure of xylem vessels and phloem sieve tubes.', 'Xylem: dead, no cytoplasm, no end walls (continuous tube), lignified walls with pits; carries water and ions upwards, passively. Phloem: living sieve tube elements with little cytoplasm and no nucleus, sieve plates, cellulose walls, and companion cells rich in mitochondria for active loading; carries sucrose and amino acids from sources to sinks, up or down.', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'Why does respiration release heat as well as producing ATP?', 'Respiration is not fully efficient: only part of the chemical energy in the respiratory substrate is transferred to ATP. The rest is released as heat, which endotherms use to keep their body temperature high and stable.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'List the four stages of aerobic respiration and where each happens.', 'Glycolysis: cytoplasm. Link reaction: mitochondrial matrix. Krebs cycle: mitochondrial matrix. Oxidative phosphorylation: inner mitochondrial membrane (cristae).', 2, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'Summarise glycolysis.', 'Hexose is phosphorylated by 2 ATP, then split into two triose phosphates. Each is oxidised (NAD → reduced NAD) and converted to GP, then to pyruvate. 4 ATP made by substrate-level phosphorylation, so net 2 ATP, 2 reduced NAD and 2 pyruvate per glucose.', 3, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'What happens in the link reaction?', 'In the matrix, pyruvate (3C) is decarboxylated (CO₂ released) and oxidised (NAD reduced). The 2C acetyl group joins coenzyme A to form acetyl CoA. No ATP is made. It happens twice per glucose.', 4, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'What does one turn of the Krebs cycle produce?', 'The acetyl group (2C) joins a 4C compound to make 6C, which is broken back down to 4C. Per turn: 2 CO₂, 3 reduced NAD, 1 reduced FAD and 1 ATP (substrate-level). Two turns per glucose.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'Explain chemiosmosis in mitochondria.', 'Electrons from reduced NAD/FAD pass along carriers in the inner membrane, releasing energy that pumps H⁺ from the matrix into the intermembrane space. H⁺ diffuses back through ATP synthase, which makes ATP from ADP + Pi.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'What is the role of oxygen in aerobic respiration?', 'Oxygen is the terminal electron acceptor. It combines with electrons and protons to form water (½O₂ + 2H⁺ + 2e⁻ → H₂O). Without it the chain stops, NAD is not regenerated, and the link reaction and Krebs cycle stop too.', 7, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'How do mitochondrial membranes help ATP synthesis?', 'Inner membrane is impermeable to H⁺ except via ATP synthase, so a gradient can form. Cristae give a large area for ETCs and ATP synthase. Small intermembrane space gives a steep gradient quickly. Inner membrane also has carrier proteins that move pyruvate, ADP and ATP between the cytoplasm side and the matrix.', 8, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'Compare the ATP yield of aerobic and anaerobic respiration.', 'Aerobic: about 30 to 32 ATP per hexose (38 often quoted as a theoretical maximum). Anaerobic: net 2 ATP, from glycolysis only. Anaerobically, pyruvate is not oxidised further, so most energy stays in lactate or ethanol.', 9, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'How does lactate affect muscle contraction?', 'Pyruvate + reduced NAD → lactate + NAD lets glycolysis continue. Lactate and H⁺ lower the pH, affecting enzymes for respiration and contraction, so force falls and fatigue sets in. Lactate is later converted back to pyruvate in the liver.', 10, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'How is ethanol formed in plant cells without oxygen?', 'Pyruvate → ethanal + CO₂ (decarboxylation). Ethanal + reduced NAD → ethanol + NAD. Ethanal is the hydrogen acceptor, NAD is regenerated for glycolysis, and the pathway is irreversible because CO₂ is lost.', 11, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'CP9: how does a respirometer measure respiration rate?', 'Organisms are sealed with soda lime, which absorbs CO₂, so O₂ uptake moves a liquid along a capillary. Volume = πr²l; divide by time (and mass). A control of glass beads corrects for temperature and pressure changes. Handle animals humanely.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'Absorption spectrum vs action spectrum', 'Absorption spectrum: light absorbed by pigment(s) at each wavelength. Action spectrum: rate of photosynthesis at each wavelength. They match closely, showing that absorbed light drives photosynthesis. Peaks are in blue-violet and red; the trough is in green.', 13, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'Why do plants have several photosynthetic pigments?', 'Chlorophyll a (reaction centre), chlorophyll b, carotene and xanthophylls each absorb different wavelengths. Together they absorb a wider range and pass energy to chlorophyll a, raising the rate in low or filtered light. Carotenoids also protect against excess light.', 14, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'CP11: how is an Rf value calculated?', 'Rf = distance moved by pigment spot ÷ distance moved by solvent front, both measured from the pencil origin line to the spot centre. It has no units and lies between 0 and 1. Carotene usually moves furthest; chlorophyll b least.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'Describe the structure of a chloroplast.', 'Envelope: double membrane. Stroma: fluid with Calvin cycle enzymes (RUBISCO), starch grains, DNA and ribosomes. Thylakoids: membrane sacs stacked into grana. Lamellae: thylakoid membranes linking grana.', 16, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'Cyclic vs non-cyclic photophosphorylation', 'Non-cyclic: PSII and PSI; electrons from water (photolysis) end on NADP; makes ATP, reduced NADP and O₂. Cyclic: PSI only; electrons return to PSI; makes ATP only. Both use electron carriers and chemiosmosis.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '5', 'Energy for Biological Processes', 'Outline the Calvin cycle and the uses of GALP.', 'In the stroma, RUBISCO fixes CO₂ with RuBP (5C) to give 2 GP (3C). GP is reduced to GALP using reduced NADP and ATP. 5 of every 6 GALP regenerate RuBP (using ATP). GALP makes hexoses, lipids, amino acids (with nitrate) and more.', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'What is aseptic technique, and what are its two purposes?', 'Working practices that prevent unwanted microorganisms contaminating a culture, and prevent the cultured microorganisms escaping to infect the worker or the environment. Examples: disinfect the bench, work near a Bunsen flame, sterilise media in an autoclave, flame the loop and bottle necks, open lids as little as possible.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Total count versus viable count: which growth-measuring methods give each?', 'Total count (live and dead cells): haemocytometer cell count, mass (biomass), and turbidity measured with a colorimeter. Viable count (living cells only): dilution plating, where each colony is assumed to grow from one living cell.', 2, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'How is a viable count calculated from a dilution plate?', 'Cells per cm³ of original culture = number of colonies × dilution factor ÷ volume plated (cm³). Use a plate with about 30–300 separate colonies. Example: 47 colonies from 0.1 cm³ of the 10⁻⁵ dilution gives 47 × 10⁵ ÷ 0.1 = 4.7 × 10⁷ cells cm⁻³.', 3, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'What causes each phase of a bacterial growth curve?', 'Lag: cells adjust and synthesise enzymes, little division. Log: plentiful nutrients, low waste, cells double at a constant rate. Stationary: nutrients running low and waste building up, so division rate equals death rate. Death: nutrients exhausted and waste toxic, so deaths exceed new cells.', 4, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'How is the mean growth rate constant, k, calculated?', 'k = (log₁₀Nₜ − log₁₀N₀) ÷ (0.301 × t), using two points on the straight log phase. N₀ and Nₜ are cell numbers at the start and end, t is the time interval, 0.301 = log₁₀2. Units: generations per hour (h⁻¹). Mean generation time = 1 ÷ k. After n generations, N = N₀ × 2ⁿ.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'How does streak plating produce a pure culture?', 'Streak the mixed culture over one area of agar, flame and cool the loop, then drag from that area into a fresh one. Repeating this carries fewer cells each time, until cells in the last area grow into separate colonies. One colony, grown from a single cell, is transferred to fresh medium to give a pure culture.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Exotoxins versus endotoxins', 'Exotoxins: usually proteins, secreted by living bacteria, often specific and potent, usually destroyed by heat (e.g. Staphylococcus). Endotoxins: lipopolysaccharides in the outer membrane of Gram-negative bacteria, released mainly when the cells die, cause general effects such as fever, inflammation and shock, relatively heat-stable (e.g. Salmonella).', 7, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'How does Mycobacterium tuberculosis cause disease?', 'By invasion of host tissue. It is inhaled in droplets and engulfed by alveolar macrophages, but its thick waxy wall resists digestion, so it multiplies inside them. Infected areas are walled off in tubercles and may stay dormant. If immunity weakens (e.g. HIV, malnutrition) it destroys lung tissue, causing cavities, a cough, weight loss and fever.', 8, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Penicillin versus tetracycline', 'Penicillin is bactericidal: it inhibits the enzymes that cross-link peptidoglycan, so new wall is weak, water enters by osmosis and the growing cell bursts. Tetracycline is bacteriostatic: it binds the 30S subunit of 70S ribosomes, stopping tRNA binding and protein synthesis, so growth and division stop and the immune system clears the bacteria.', 9, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'How does antibiotic resistance spread in a bacterial population?', 'A random mutation (present before treatment) gives some cells resistance, e.g. a β-lactamase that breaks down penicillin. The antibiotic kills susceptible cells; resistant cells survive, divide and pass on the allele, so its frequency rises. Resistance genes on plasmids also pass between species by conjugation (horizontal transfer).', 10, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Stem rust (Puccinia graminis) on wheat: transmission, infection, effect', 'Transmission: wind-borne spores from pustules (also rain splash, clothing, machinery). Infection: on a wet surface a spore germinates and a hypha enters through a stoma; haustoria absorb sugars from cells. Effect: sugars diverted from grain, epidermis ruptured (more water loss), less photosynthesis, stems collapse, shrivelled grain.', 11, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Influenza virus: transmission, infection, effect', 'Transmission: droplets, aerosols, contaminated surfaces. Infection: haemagglutinin binds receptors on airway epithelial cells; the virus replicates inside and new particles bud out, released by neuraminidase. Effect: infected cells die, ciliated epithelium is lost so secondary bacterial pneumonia can follow; cytokines cause fever and aches.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Malaria (Plasmodium): transmission, infection, effect', 'Transmission: female Anopheles mosquito (the vector) injects parasites in saliva during a blood meal; also infected blood and mother to fetus. Infection: parasites multiply in liver cells, then in red blood cells, which burst. Effect: repeated fever and shivering, anaemia; with P. falciparum, blocked small vessels cause cerebral malaria and organ failure.', 13, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Outline the humoral immune response.', 'A macrophage presents antigen on MHC proteins. A T helper cell with a complementary receptor is activated and releases cytokines. A B cell with a complementary receptor is selected (clonal selection) and divides by mitosis (clonal expansion). Most clone cells become plasma cells that secrete specific antibodies; some become B memory cells.', 14, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Outline the cell-mediated immune response.', 'Infected body cells and antigen-presenting macrophages display antigen on MHC proteins. Activated T helper cells release cytokines that stimulate matching T killer cells to divide. T killer cells bind infected cells showing the antigen and release perforins, which make pores; enzymes enter and trigger apoptosis. Some T cells become memory cells.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Why is the secondary immune response faster and larger than the primary?', 'The primary response leaves many long-lived B and T memory cells, already specific to the antigen. On re-exposure there is no need to select from a few matching lymphocytes: memory B cells rapidly become plasma cells and memory T cells rapidly form T helper and T killer cells. Antibody concentration rises faster, higher and for longer.', 16, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'Natural/artificial, active/passive immunity: one example of each', 'Natural active: recovering from an infection. Artificial active: vaccination. Natural passive: antibodies crossing the placenta or in breast milk (colostrum). Artificial passive: injected antibodies, e.g. antitoxin after a snake bite. Active immunity is slow to develop but long-lasting (memory cells); passive is immediate but short-lived.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '6', 'Microbiology and Pathogens', 'What is herd immunity, and how is the threshold estimated?', 'When enough of a population is immune, an infected person is unlikely to meet a susceptible one, so transmission chains die out, protecting those who cannot be vaccinated. Threshold ≈ 1 − 1/R₀. Measles (R₀ about 12–18) needs about 92–94% immune, so about 95% vaccine coverage is the target; R₀ = 2 needs about 50%.', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'What is the genome?', 'All of the DNA in a cell or organism, including non-coding DNA such as introns, regulatory sequences and repeats. In humans only about 1–2% of the roughly 3.1 × 10⁹ base pairs codes for proteins.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'What happens at each stage of a PCR cycle?', 'Denaturation (about 95 °C): hydrogen bonds break and the strands separate. Annealing (about 50–65 °C): primers bind to either end of the target region. Extension (about 72 °C): Taq polymerase adds nucleotides to the primers. The number of copies ideally doubles each cycle: copies = starting copies × 2ⁿ.', 2, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'Why is Taq polymerase used in PCR?', 'It comes from Thermus aquaticus, a bacterium from hot springs, so it is heat-stable. It is not denatured at 95 °C and does not need to be added again each cycle.', 3, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'How can gene sequencing link a mutation to a genetic condition?', 'The gene is amplified by PCR and sequenced, then compared with the reference sequence. Reading codons from the start codon predicts the amino acid sequence, showing how a mutation changes the protein, e.g. glutamic acid replaced by valine in sickle cell disease.', 4, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'What are short tandem repeats (STRs) and why are they used in DNA profiling?', 'Non-coding regions where a short sequence (often 2–5 bases) is repeated one after another. The number of repeats at each locus varies greatly between people, and each person has two alleles per locus, one from each parent.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'How is a paternity test interpreted?', 'Match each band in the child to a band in the mother first. Every remaining band must be present in the biological father. A man lacking any remaining band is excluded; a man with all of them at many loci is very likely to be the father.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'How do transcription factors regulate gene expression?', 'They are proteins that bind specific DNA sequences in promoters or enhancers. Activators help RNA polymerase bind, increasing transcription; repressors block it, decreasing transcription. Example: oestrogen binds a receptor and the complex acts as a transcription factor.', 7, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'What is alternative splicing?', 'Pre-mRNA is processed in different ways so different combinations of exons are kept in the mature mRNA. The mRNAs are translated into different polypeptides, so one gene can code for more than one protein. It happens in the nucleus, after transcription.', 8, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'How do DNA methylation and histone acetylation affect transcription?', 'DNA methylation: methyl groups added to cytosine (often at CpG sites in promoters) usually silence the gene. Histone acetylation: reduces the histones'' positive charge so they hold DNA less tightly, chromatin loosens and transcription increases. Neither changes the base sequence.', 9, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'How does non-coding RNA change gene expression?', 'miRNA and siRNA bind complementary sequences in target mRNA, causing it to be broken down or blocking translation. Long non-coding RNAs such as Xist coat one X chromosome in female mammals, making it condense and become inactive.', 10, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'Why is epigenetic modification important in differentiation?', 'All body cells have the same genes. Genes needed by a cell type stay accessible, while others are silenced by DNA methylation and histone deacetylation. The marks are copied during mitosis, so daughter cells stay the same cell type.', 11, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'Totipotent, pluripotent and multipotent: what is the difference?', 'Totipotent: any cell type including placenta; the zygote and early embryo cells. Pluripotent: any body cell but not placenta; inner cell mass of the blastocyst and iPS cells. Multipotent: a limited range of related cells, e.g. bone marrow stem cells forming blood cells.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'How are iPS cells made, and why may they be less problematic than embryonic stem cells?', 'Genes for the transcription factors Oct4, Sox2, Klf4 and c-Myc are introduced into fibroblasts, reprogramming them to a pluripotent state. No embryo is destroyed, the donor can consent, and cells from the patient are not rejected. Risks remain: tumours, low efficiency.', 13, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'What roles do restriction endonucleases and DNA ligase play in making recombinant DNA?', 'Restriction endonucleases cut DNA at specific recognition sequences, often leaving sticky ends; the gene and vector are cut with the same enzyme so the ends are complementary. DNA ligase forms phosphodiester bonds to seal the sugar–phosphate backbones.', 14, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'Name four ways of getting recombinant DNA into cells.', 'Plasmids taken up by bacteria (transformation, e.g. calcium ions and heat shock). Modified viruses, e.g. bacteriophages or retroviruses. Agrobacterium tumefaciens and its Ti plasmid for dicot plants such as soya. Gene guns firing DNA-coated gold or tungsten particles, e.g. into cereals.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'How does replica plating identify recombinant bacteria?', 'The plasmid has ampicillin and tetracycline resistance genes; the gene is inserted into the tetracycline gene, inactivating it. Grow on ampicillin, press a velvet pad on and transfer to tetracycline. Colonies missing from the tetracycline plate are recombinant; take them from the master plate.', 16, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'What is a knockout mouse and why is it a useful model?', 'A mouse with a specific gene made non-functional, compared with wild-type mice to reveal the gene''s role. Mice are mammals with similar genes, breed quickly and inbred strains are near-identical. Limits: results may not apply to humans, and some knockouts are lethal to embryos.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '7', 'Modern Genetics', 'How has soya been genetically modified?', 'Herbicide-tolerant soya has a bacterial EPSPS gene not inhibited by glyphosate, so weeds can be sprayed without harming the crop. High-oleic soya has FAD2 silenced, so its oil has more monounsaturated and less polyunsaturated fat; fewer C=C bonds means less oxidation and no need for hydrogenation.', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'What is the only process that produces new alleles?', 'Mutation: a change in the base sequence of DNA. Meiosis and fertilisation only reshuffle alleles that already exist. Only mutations in cells that give rise to gametes are inherited.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'How does crossing over produce genetic variation?', 'In prophase I, homologous chromosomes pair as bivalents. Non-sister chromatids break and rejoin at chiasmata, exchanging equivalent sections. This produces recombinant chromatids with new combinations of alleles on the same chromosome.', 2, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'How does independent assortment produce genetic variation?', 'At metaphase I each bivalent lines up with a random orientation, independent of the others, so gametes get a random mix of maternal and paternal chromosomes. With n pairs there are 2ⁿ combinations (2²³ ≈ 8.4 million in humans).', 3, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'How does random fertilisation add to genetic variation?', 'Any male gamete can fuse with any female gamete, so which alleles combine in a zygote is a matter of chance. The number of possible zygotes is the product of the gamete types from each parent, so every individual (apart from identical twins) is unique.', 4, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'Genotype and phenotype', 'Genotype: the alleles an organism carries for the gene(s) considered, e.g. Tt. Phenotype: the characteristics it shows, which result from its genotype interacting with its environment, e.g. a tall pea plant.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'Explain codominance using the ABO blood groups.', 'Iᴬ and Iᴮ are codominant: both are expressed in IᴬIᴮ, giving group AB with A and B antigens. Both are dominant to Iᴼ. Group A = IᴬIᴬ or IᴬIᴼ; group B = IᴮIᴮ or IᴮIᴼ; group O = IᴼIᴼ.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'What are multiple alleles?', 'A gene with three or more alleles in a population, e.g. Iᴬ, Iᴮ and Iᴼ for the ABO gene. Each diploid individual still carries only two of them.', 7, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'What is a test cross and what does it show?', 'Crossing an individual with the dominant phenotype with a homozygous recessive. All dominant offspring means the parent was homozygous (TT); 1 : 1 dominant : recessive means it was heterozygous (Tt).', 8, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'Ratios for two unlinked, non-interacting genes', 'AaBb × AaBb gives 9 : 3 : 3 : 1 (the two 3 : 1 ratios multiplied). AaBb × aabb (test cross) gives 1 : 1 : 1 : 1. Each gamete carries one allele of each gene, e.g. AB, Ab, aB, ab.', 9, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'What is autosomal linkage?', 'Two genes whose loci are on the same autosome. Their alleles tend to be inherited together, so they do not assort independently. A test cross gives two large parental classes and two small recombinant classes, from crossing over between the loci.', 10, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'How is recombination frequency calculated and interpreted?', 'Recombination frequency = recombinant offspring ÷ total offspring × 100. Below 50% shows the genes are linked; unlinked genes give 50%. The further apart the loci, the higher the frequency. E.g. Drosophila body colour and wing length: 391 ÷ 2300 × 100 = 17%.', 11, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'Explain the sex linkage of haemophilia.', 'The recessive allele (Xʰ) is on the X chromosome, with no matching locus on the Y. Males (XY) are hemizygous, so XʰY is affected. Females need XʰXʰ; XᴴXʰ females are carriers. Sons get their X from their mother, so affected fathers cannot pass it to sons.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'Carrier mother × unaffected father (XᴴXʰ × XᴴY): outcomes', 'Offspring: XᴴXᴴ, XᴴXʰ (carrier), XᴴY, XʰY (affected) in equal proportions. Probability a child is an affected son = 1/4. Probability a son is affected = 1/2. No daughters are affected; half are carriers.', 13, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'Steps of a chi squared test on a genetic cross', '1) Null hypothesis: no significant difference between observed and expected. 2) Calculate expected numbers from the ratio. 3) χ² = Σ(O − E)² ÷ E using raw counts. 4) Degrees of freedom = categories − 1. 5) Compare with the critical value at p = 0.05: below it, accept the null hypothesis; equal to or above it, reject.', 14, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'Stabilising versus disruptive selection', 'Stabilising: phenotypes near the mean favoured, extremes selected against; mean unchanged, spread (standard deviation) reduced; maintains continuity in a stable environment. Disruptive: both extremes favoured over intermediates; distribution becomes bimodal; can lead to reproductive isolation and speciation.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'What is genetic drift?', 'A change in allele frequencies caused by chance, not by an allele giving an advantage. The alleles passed on each generation are a random sample of the gene pool. It is strongest in small populations, can lose or fix alleles, and does not make a population better adapted.', 16, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'Population bottleneck versus founder effect', 'Both are forms of genetic drift that reduce genetic diversity by chance. Bottleneck: most of an existing population dies, e.g. hunting of the northern elephant seal. Founder effect: a few individuals start a new isolated population, e.g. high frequency of Ellis–van Creveld syndrome in the Old Order Amish.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '8', 'Origins of Genetic Variation', 'State the Hardy–Weinberg equations and conditions.', 'p + q = 1 (allele frequencies). p² + 2pq + q² = 1 (AA, Aa and aa genotype frequencies). Conditions: very large population, random mating, no selection, no mutation, no migration. A change in allele frequencies over time shows the population is evolving.', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'What is homeostasis, and why is it described as a dynamic equilibrium?', 'Homeostasis is keeping the internal environment (e.g. temperature, pH, water potential) within narrow limits. It is dynamic because the variables are constantly disturbed and fluctuate slightly around a set point, with corrective mechanisms continually pulling them back.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'Negative feedback vs positive feedback', 'Negative feedback: a change from the set point triggers a response that reverses it, so the stimulus and the response then decrease (e.g. ADH and plasma concentration). Positive feedback: the response amplifies the change until an outside event ends it (e.g. oxytocin in childbirth; Na⁺ entry opening more Na⁺ channels in an action potential).', 2, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'Two modes of hormone action', 'Adrenaline (water-soluble) binds a surface receptor → adenylyl cyclase activated → ATP to cAMP (second messenger) → protein kinase A activates enzymes; fast and amplified. Oestrogen (lipid-soluble steroid) diffuses into the cell and binds a receptor that is a transcription factor → changes gene transcription; slower (hours).', 3, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'Effects of auxin', 'Cell elongation in shoots (proton pumps lower wall pH, expansins loosen cellulose, cell stretches as it takes in water); apical dominance (suppresses lateral buds); promotes root formation, e.g. in cuttings. Roots are more sensitive: high concentrations that promote shoot growth inhibit root elongation.', 4, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'How do auxin and cytokinin control lateral buds?', 'They act antagonistically. Auxin from the apical bud inhibits lateral buds; cytokinin from the roots (in the xylem) stimulates cell division and bud growth. The auxin:cytokinin ratio decides: high near the apex, so buds stay dormant; removing the apex shifts the balance to cytokinin, so buds grow.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'How does gibberellin trigger starch breakdown in a germinating cereal grain?', 'The grain absorbs water and the embryo releases gibberellin. It diffuses to the aleurone layer, where it causes DELLA proteins to be broken down, so the amylase gene is transcribed. Amylase is secreted into the endosperm and hydrolyses starch to maltose for the embryo. CP14 measures this with clear zones on starch agar.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'Phytochrome: the two forms and how they interconvert', 'Pr absorbs red light (about 660 nm) and becomes Pfr. Pfr absorbs far-red light (about 730 nm) and becomes Pr; in the dark Pfr slowly reverts to Pr. Daylight has more red than far-red, so Pfr builds up by day and falls at night. Pfr is the active form and alters gene expression.', 7, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'Short-day vs long-day plants', 'Plants measure the uninterrupted dark period. Short-day plants flower when nights exceed a critical length: Pfr inhibits their flowering, so Pfr must fall low. Long-day plants flower when nights are short: Pfr promotes their flowering. A red flash mid-night prevents short-day flowering; far-red straight after cancels it.', 8, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'How does an endotherm respond when its core temperature falls?', 'Thermoreceptors in the hypothalamus (and skin) detect the change; the heat gain centre acts via the autonomic nervous system. Skin arterioles constrict, so less blood flows near the surface; little sweat; hair erector muscles contract to trap air; shivering releases heat from respiration; metabolic rate rises. Behaviour: shelter, huddling, curling up.', 9, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'Functions of the medulla oblongata, cerebellum, cerebrum and hypothalamus', 'Medulla oblongata: controls breathing and heart rate. Cerebellum: balance and coordination of movement. Cerebrum: initiates voluntary movement (also thought, memory, language). Hypothalamus: temperature regulation and osmoregulation.', 10, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'How is the resting potential of about −70 mV set up?', 'Na⁺/K⁺ pumps move 3 Na⁺ out for every 2 K⁺ in, using ATP. At rest K⁺ channels are open and most Na⁺ channels closed, so K⁺ diffuses out, making the inside negative, until the electrical pull inward balances the concentration gradient. Large negative proteins stay inside.', 11, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'Stages of an action potential', 'Stimulus opens voltage-gated Na⁺ channels; at threshold (about −55 mV) many more open (positive feedback) and the inside reaches about +40 mV. Na⁺ channels close and K⁺ channels open: repolarisation. K⁺ channels close slowly: hyperpolarisation. Pumps restore −70 mV. The refractory period makes impulses discrete and one-way.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'Why is conduction faster in myelinated axons?', 'Myelin (from Schwann cells) insulates the axon, so depolarisation can occur only at the nodes of Ranvier, where Na⁺ channels are concentrated. Local currents flow from node to node and the action potential jumps between them (saltatory conduction). Fewer ions move, so less ATP is needed. Wider axons also conduct faster.', 13, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'Events at a cholinergic synapse', 'Action potential arrives → voltage-gated Ca²⁺ channels open, Ca²⁺ enters the knob → vesicles fuse and release ACh by exocytosis → ACh diffuses across the cleft and binds receptors → Na⁺ channels open, postsynaptic membrane depolarises (EPSP) → acetylcholinesterase hydrolyses ACh to choline and ethanoic acid, which are recycled.', 14, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'How do nicotine, lidocaine and cobra venom act?', 'Nicotine mimics ACh: binds and opens ACh receptors and is not broken down by acetylcholinesterase, so stimulation lasts longer. Lidocaine blocks voltage-gated Na⁺ channels, so no action potentials form: local anaesthesia. Cobra venom blocks ACh receptors, so muscles cannot be stimulated: paralysis.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'How does light on a rod lead to an impulse in the optic nerve?', 'Retinal changes from cis to trans and rhodopsin breaks down into opsin and retinal (bleaching). Na⁺ channels close, so the rod hyperpolarises and stops releasing glutamate, which was inhibiting the bipolar neurone. The bipolar neurone depolarises and triggers action potentials in a ganglion cell.', 16, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'How is heart rate adjusted by the autonomic nervous system?', 'Baroreceptors (pressure) and chemoreceptors (CO₂, pH) in the aorta and carotid arteries send impulses to the cardiac centre in the medulla oblongata. Sympathetic nerve → noradrenaline at the SAN → faster. Parasympathetic (vagus) nerve → acetylcholine at the SAN → slower. Adrenaline from the adrenal medulla also raises heart rate.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '9', 'Control Systems', 'How does the loop of Henle act as a counter-current multiplier?', 'The ascending limb actively pumps Na⁺ and Cl⁻ into the medulla but is impermeable to water. The descending limb is permeable to water, which leaves by osmosis. Flow in opposite directions multiplies the effect, building a steep solute gradient. Water then leaves the collecting duct by osmosis (more when ADH is present). Longer loops, as in kangaroo rats, give steeper gradients.', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'What is an ecosystem, and how large can one be?', 'The community of organisms in an area together with its abiotic conditions and the interactions between them. Ecosystems range in size from a rock pool or rotting log to a lake, a forest or the whole biosphere; the boundaries are chosen by the investigator.', 1, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'What is a trophic level? Give the first four.', 'The feeding position of an organism, counted in energy-transfer steps from the producers. 1: producers; 2: primary consumers (herbivores); 3: secondary consumers; 4: tertiary consumers. An omnivore can occupy more than one level.', 2, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Pyramid of numbers: one advantage and one disadvantage.', 'Advantage: quick and easy to obtain by counting, with no organisms killed. Disadvantage: ignores size, so it can be inverted or distorted (one oak tree supporting thousands of caterpillars, or parasites).', 3, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Pyramid of dry biomass: advantages and disadvantages.', 'Advantages: allows for organism size; drying removes variable water content. Disadvantages: organisms must be killed and dried; shows standing crop at one time only; can be inverted (fast-reproducing phytoplankton); equal masses of tissue don''t contain equal energy.', 4, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Pyramid of energy: advantages and disadvantages.', 'Advantages: includes time and energy content of tissues; never inverted; allows fair comparison of ecosystems and transfer efficiencies. Disadvantages: hard to collect (a year''s biomass plus calorimetry); omnivores are hard to allocate to one level. Units: kJ m⁻² yr⁻¹.', 5, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Types of quadrat and what each is best for.', 'Frame quadrat: counts or cover in a square frame. Gridded quadrat: 100 squares, count those at least half covered for % cover. Point quadrat: row of pins lowered in turn, recording every plant touched; most objective for low, dense vegetation.', 6, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Line transect vs belt transect.', 'Both are used along an environmental gradient. Line transect: records organisms touching a tape (presence and position only). Belt transect: quadrats placed along the tape, continuously or at intervals, so abundance is recorded too; results can be drawn as a kite diagram.', 7, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Measures of abundance: when to use each.', 'Individual counts: organisms easy to tell apart (daisies, limpets). Percentage cover: grasses, mosses, where individuals can''t be separated. Frequency: % of quadrats containing the species. ACFOR (Abundant, Common, Frequent, Occasional, Rare): rapid but subjective surveys.', 8, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Formulae for estimating population size.', 'Quadrats: mean per quadrat × (site area ÷ quadrat area). Mark-release-recapture (Lincoln index): N = (M × n) ÷ m, where M = number marked, n = total in second sample, m = marked in second sample. Assumes marks are harmless, full mixing and no births, deaths or migration.', 9, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'When do you use a t-test, Spearman''s rank or chi-squared?', 't-test: compare the means of two samples of continuous, roughly normal data (df = n₁ + n₂ − 2). Spearman''s rank: test for correlation between two variables on the same samples (at least 5 pairs). Chi-squared: compare observed with expected frequencies in categories. Reject the null hypothesis if the value ≥ critical value at p = 0.05.', 10, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Spearman''s rank formula and how to interpret rs.', 'rs = 1 − (6Σd²) ÷ (n(n² − 1)). Rank both variables the same way, find d for each pair, square and sum. rs ranges from +1 (perfect positive) to −1 (perfect negative). A significant correlation does not show causation.', 11, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Define GPP and NPP.', 'GPP: rate at which producers convert light energy into chemical energy by photosynthesis, per unit area per unit time. NPP: rate at which energy is stored in new producer biomass after producer respiration is subtracted. NPP = GPP − R. NPP is the energy available to consumers and decomposers.', 12, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'How do you calculate the efficiency of energy transfer, and why is it low?', 'Efficiency (%) = energy transferred to higher level ÷ energy available at lower level × 100. Low because parts are not eaten, indigestible material is egested, energy is lost in urine, and much is released in respiration and lost as heat (especially in endotherms).', 13, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Stages of the nitrogen cycle and the bacteria involved.', 'Fixation: N₂ → NH₄⁺ (Rhizobium in legume nodules, Azotobacter), using nitrogenase. Ammonification: proteins and urea → NH₄⁺ (saprobionts). Nitrification: NH₄⁺ → NO₂⁻ (Nitrosomonas) → NO₃⁻ (Nitrobacter), needs oxygen. Denitrification: NO₃⁻ → N₂ in anaerobic, waterlogged soil.', 14, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Describe primary succession from bare rock.', 'Pioneers (lichens, mosses) colonise and weather rock; when they die, humus forms a thin soil. Grasses and ferns establish and outcompete them; soil deepens and holds more water and ions. Shrubs, then birch, then slower-growing trees follow. Climax: e.g. oak woodland in lowland Britain.', 15, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Climatic climax vs plagioclimax.', 'Climatic climax: set mainly by temperature and rainfall, e.g. tropical rainforest, temperate deciduous woodland, boreal forest, tundra. Plagioclimax: human activity stops succession early, e.g. grazing keeps chalk downland, burning keeps heather moorland. If management stops, succession resumes.', 16, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'Biotic and abiotic factors affecting population size.', 'Abiotic: temperature (enzyme activity), light (photosynthesis), water, soil pH and mineral ions, oxygen, wind, salinity. Biotic: intraspecific and interspecific competition, predation, disease, parasitism, food supply. Density-dependent factors (competition, predation, disease) have more effect as density rises; frost, flood and drought are density-independent.', 17, 'alevel'),
  ('Biology', 'Edexcel B', '10', 'Ecosystems', 'What is CITES, and what are its limitations?', 'An international agreement (1973, in force 1975) controlling cross-border trade in wild species. Appendix I: commercial trade banned; II: export permit needed; III: permits from the listing country. Limitations: controls only international trade, not habitat loss or local hunting; depends on national enforcement; illegal trade continues.', 18, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP1: investigate a factor affecting the initial rate of an enzyme-controlled reaction.', 'E.g. temperature with amylase: amylase and 1% starch in separate tubes in a water bath (20-60°C), equilibrate 5 min. Mix, start the stopwatch; every 30 s put a drop on iodine on a spotting tile until it stays yellow-brown (no starch). 3 repeats. IV: temperature (or pH, enzyme, substrate or inhibitor concentration); DV: time to end-point; control volumes, concentrations, pH (buffer). Safety: iodine irritant and stains, gloves; care with hot water baths. Analysis: rate = 1/t (a mean rate estimating initial rate); bell-shaped curve, optimum ~37°C, denaturation above; Q₁₀ ≈ 2 below the optimum.', 1, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP2: use a light microscope with stage and eyepiece micrometers, and draw cells from a specialised tissue.', 'Fit the eyepiece graticule; focus on the stage micrometer; line up the scales. Length of 1 eyepiece unit = stage distance ÷ number of eyepiece units; calibrate for each objective. Replace with a specialised tissue slide (e.g. palisade mesophyll), focus on low power then high. Measure several cells in eyepiece units and convert to μm; draw 3-5 cells. Safety: handle slides carefully; never use direct sunlight. Analysis: actual size = units x calibrated value; magnification = image size ÷ actual size (1 mm = 1000 μm); mean size. Drawings: sharp pencil, no shading, ruled labels, title and magnification.', 2, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP3: prepare a temporary squash of a root tip to show the stages of mitosis.', 'Cut 5 mm garlic or onion root tips; 1 mol dm⁻³ HCl at 55-60°C for ~5 min (breaks down the middle lamella and stops division). Rinse, blot, keep only the terminal 1-2 mm (meristem). Add toluidine blue or acetic orcein, macerate, wait 2 min. Coverslip, filter paper, press firmly and vertically to give a single layer. Find the meristem on low power, identify stages on high power, count cells in each stage over several fields. Safety: HCl irritant, eye protection; stains, gloves. Analysis: mitotic index = cells in mitosis ÷ total cells; proportion in each stage reflects its relative duration.', 3, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP4: investigate the effect of sucrose concentration on pollen tube growth or germination.', 'Put a drop of each sucrose solution (e.g. 0-20%) in a labelled cavity slide. Brush pollen from ripe anthers thinly onto each drop; coverslip; keep in a humid chamber at constant temperature (e.g. 25°C). After 30-60 min count grains with a tube (50+ per slide) and measure tube lengths with a calibrated eyepiece graticule. IV: sucrose concentration; DV: % germination, tube length; control time, temperature. Safety: pollen allergies, avoid inhaling, wash hands. Analysis: % germination = grains with tube ÷ total x 100; best at intermediate concentration (respiratory substrate and water potential).', 4, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP5: investigate the effect of temperature on beetroot membrane permeability.', 'Cut uniform beetroot discs with a cork borer; rinse thoroughly until water runs clear. Place one disc per tube in 5 cm³ distilled water; incubate 20 min at each temperature (20-70°C). Remove beetroot; measure absorbance of the solution with a colorimeter; 3 repeats, means. IV: temperature; DV: absorbance; control disc size, water volume, time, beetroot source. Safety: cut on a tile away from the body; tongs for hot tubes. Analysis: plot mean absorbance vs temperature; sharp rise above ~40°C as membrane proteins denature and the phospholipid bilayer loses integrity, letting betacyanin diffuse out.', 5, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP6: determine the water potential of plant cells.', 'Cut equal potato cylinders with a cork borer from the same potato; blot and weigh each. Place one in each sucrose solution (0-1.0 mol dm⁻³) for 30-60 min; remove, blot the same way, reweigh. 3 repeats per concentration. IV: sucrose concentration; DV: % change in mass. Safety: sharp tools, cut on a white tile. Analysis: % change = (final − initial) ÷ initial x 100; plot against concentration; where the line crosses 0% is the isotonic point. Convert that concentration to water potential (kPa) using a table or graph. Use % change so different starting masses are comparable.', 6, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP7: dissect an insect to show the structure of the gas exchange system.', 'Use a humanely killed locust or cockroach from a supplier. Find spiracles along the thorax and abdomen with a hand lens. Pin dorsal side up; cut along the dorsal midline of the abdomen with scissor points up; pin back the body wall and cover with water or saline so air-filled tracheae show as silvery tubes. Trace tracheae inwards; mount a piece to see chitin rings and tracheoles under the microscope. Safety and ethics: sharp tools, count pins; locust allergies (gloves); fewest specimens, treat with respect. Analysis: draw and label; O₂ path spiracle to trachea to tracheole to cells by diffusion.', 7, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP8: investigate factors affecting water uptake by plant shoots using a potometer.', 'Cut the shoot underwater and assemble the potometer underwater to avoid air locks; seal joints with Vaseline; equilibrate 5 min. Introduce an air bubble and record distance moved per minute. Test conditions such as fan (wind), plastic bag (humidity), bright light, darkness; reset the bubble with the reservoir; 3 repeats. IV: environmental factor; DV: rate of bubble movement; control shoot, temperature and other factors. Safety: sharp tools; keep electrics away from water. Analysis: volume = πr² x distance; rate = volume ÷ time. Measures uptake, taken as approximately equal to transpiration.', 8, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP9: investigate factors affecting the rate of aerobic or anaerobic respiration using a respirometer.', 'Respirometer with germinating seeds and soda lime (separated by cotton wool); control with glass beads. Seal, water bath, equilibrate 5 min; record movement of a coloured fluid drop per minute for 10 min, at different temperatures. Anaerobic: yeast in glucose, no soda lime, collect CO₂ in a gas syringe. IV: temperature; DV: rate of drop movement. Safety: soda lime is corrosive, gloves and eye protection Analysis: soda lime absorbs CO₂ so movement is O₂ uptake; rate = distance ÷ time; roughly doubles per 10°C up to an optimum; beads control for pressure changes.', 9, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP10: investigate the effects of different wavelengths of light on the rate of photosynthesis.', 'Pondweed (e.g. Elodea), cut end up, in NaHCO₃ solution; acclimatise. Place a coloured filter (red, blue, green) between the lamp and tube, with a heat shield. Check intensity with a light meter and adjust distance to equalise it. Collect gas over a fixed time in a photosynthometer and measure volume; 3 repeats; dark control. IV: wavelength (colour); DV: rate of gas production; control intensity, temperature, CO₂. Safety: keep lamps and cables away from water; lamps get hot. Analysis: highest in blue and red, lowest in green; compare with chlorophyll absorption spectra (action vs absorption spectrum).', 10, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP11: investigate the presence of different chloroplast pigments using chromatography.', 'Grind leaves with sand and a little propanone. Draw a pencil origin 1.5 cm from the bottom of the paper or TLC plate. Build up a small concentrated spot with a capillary tube, drying between applications. Stand in solvent, origin above the solvent level; close the container. Remove when the front nears the top, mark it immediately; measure each spot''s distance from the origin. Safety: propanone and solvents are highly flammable, no flames, ventilate. Analysis: Rf = spot distance ÷ solvent front distance; carotene moves furthest, then xanthophyll, chlorophyll a, chlorophyll b least.', 11, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP12: investigate the rate of growth of bacteria in liquid culture.', 'Aseptically add a fixed volume of non-pathogenic bacteria to sterile nutrient broth at constant temperature (e.g. 25°C). Sample aseptically every 30-60 min. Measure turbidity in a colorimeter (zeroed with sterile broth), or serially dilute, spread on agar, incubate and count plates with 30-300 colonies. Safety: aseptic technique, do not open plates after incubation, autoclave before disposal. Analysis: cells = colonies x dilution factor; plot log₁₀ cells vs time (lag, log, stationary, death); k = (log₁₀Nt − log₁₀N₀) ÷ (0.301 x t). Turbidity also counts dead cells.', 12, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP13: isolate individual species from a mixed culture of bacteria using streak plating.', 'Disinfect bench, work near a Bunsen. Flame the loop red hot and cool; flame the bottle neck, take a loopful of mixed culture (e.g. Micrococcus luteus and E. coli K-12). Streak across one edge (area 1); flame and cool the loop, turn 90°, drag from area 1 into area 2; repeat for areas 3 and 4. Tape lid with two strips, invert, incubate at 25°C for 48 h. Subculture one separate colony onto a fresh plate for a pure culture. Safety: aseptic technique, do not open after incubation, autoclave. Analysis: describe colonies; each isolated colony grew from one cell so is one species.', 13, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP14: investigate the effect of gibberellin on the production of amylase in germinating cereals using a starch agar assay.', 'Cut barley grains in half; keep the halves without the embryo (the natural source of gibberellin). Surface-sterilise in dilute bleach, rinse in sterile water. Soak in a range of gibberellic acid concentrations, or water (control). Place cut face down on starch agar with sterile forceps; tape, incubate at ~25°C for 24-48 h. Remove grains, flood with iodine, measure clear zones. IV: gibberellin concentration; DV: zone area. Safety: bleach irritant, eye protection; autoclave plates. Analysis: area = πr²; bigger zone = more amylase; gibberellin switches on amylase gene transcription in the aleurone layer.', 14, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP15: investigate the effect of different sampling methods on estimates of the size of a population.', 'Mark a study area (e.g. 10 m x 10 m) with two tapes at right angles; pick an easily counted species (e.g. daisies). Place quadrats at random coordinates and count individuals. Repeat varying quadrat size, number of quadrats, or random vs systematic placement; use a running mean for sample size; do a full count if possible. Mobile animals: mark-release-recapture. Safety and ethics: fieldwork risk assessment; harmless marks, return animals, avoid trampling. Analysis: estimate = mean per quadrat x (site area ÷ quadrat area); N = (M x n) ÷ m; compare with the true count and SD to judge accuracy and precision.', 15, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Outline CP16: investigate the effect of one abiotic factor on the distribution or morphology of one species.', 'Lay a transect across a gradient (e.g. stream bank to drier ground, canopy to open). Place quadrats at regular intervals (e.g. every 2 m); record abundance of the chosen species (percentage cover or count); measure the abiotic factor (e.g. soil moisture, light, pH, temperature) at each point, at the same time of day. Morphology version: measure a feature (e.g. leaf area of ivy) where the factor differs. Safety: fieldwork risk assessment, wash hands after soil. Analysis: kite diagram or bar chart; Spearman''s rank; the correlation is significant if rs exceeds the critical value at p ≤ 0.05.', 16, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Practical skills: how is an eyepiece graticule calibrated, and how is magnification calculated?', 'Line up the eyepiece graticule with a stage micrometer of known divisions (e.g. 10 μm). Count the eyepiece units that match a known stage distance; 1 eyepiece unit = stage distance ÷ number of units. The graticule has no units until calibrated, and must be recalibrated for each objective lens. Actual size = eyepiece units x calibrated value. Magnification = image size ÷ actual size, with both in the same units (1 mm = 1000 μm). Used in CP2 and CP4.', 17, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Practical skills: what is the difference between accuracy and precision, and what does standard deviation show?', 'Accuracy is how close a result is to the true value (e.g. a population estimate compared with a full count in CP15). Precision is how close repeat results are to each other. Standard deviation measures the spread of repeat values around the mean: a small SD means more precise data; overlapping mean ± SD ranges suggest a difference may not be significant. Improve both by random sampling, enough repeats (use a running mean to decide) and identical methods for every repeat.', 18, 'alevel'),
  ('Biology', 'Edexcel B', 'CP', 'Core Practicals', 'Practical skills: when is Spearman''s rank correlation used, and how is the result interpreted?', 'Use it to test for a correlation between two variables where one or both are ordinal or not normally distributed, e.g. species abundance vs an abiotic factor along a transect (CP16). Rank each data set, calculate rs, and compare with the critical value for the number of pairs at p ≤ 0.05. If rs exceeds the critical value, the correlation is significant (reject the null hypothesis of no correlation). rs near +1 or −1 is a strong positive or negative correlation. Correlation does not show cause.', 19, 'alevel');
